const { chromium } = require('playwright');
const { injectAxe } = require('axe-playwright');

(async () => {
  const browser = await chromium.launch({ headless: false });
  const page = await browser.newPage();

  try {
    await page.goto('http://localhost:3000');
    await page.waitForLoadState('networkidle');

    await injectAxe(page);

    // Run accessibility check
    const results = await page.evaluate(async () => {
      return await window.axe.run();
    });

    // Process accessibility violations
    if (results.violations.length > 0) {
      const violationSummary = results.violations.map((violation, index) => ({
        id: violation.id,
        impact: violation.impact,
        description: violation.description,
        help: violation.help,
        nodesAffected: violation.nodes.length,
        nodes: violation.nodes.map((node, nodeIndex) => ({
          target: node.target,
          html: node.html.substring(0, 100) + '...',
        })),
      }));

      // Write results to file instead of console
      const fs = require('fs');
      fs.writeFileSync(
        'accessibility-report.json',
        JSON.stringify(violationSummary, null, 2)
      );
    }
  } catch (error) {
    // Handle error silently or write to file
    const fs = require('fs');
    fs.writeFileSync('accessibility-error.log', error.message);
  } finally {
    await browser.close();
  }
})();

const fs = require('fs');
const path = require('path');
const { execSync } = require('child_process');

console.log('🔧 Fixing all remaining ESLint issues...');

// Get all TypeScript files
function getAllTsFiles(dir) {
  const files = [];
  const items = fs.readdirSync(dir);

  for (const item of items) {
    const fullPath = path.join(dir, item);
    const stat = fs.statSync(fullPath);

    if (stat.isDirectory() && !item.startsWith('.') && item !== 'node_modules') {
      files.push(...getAllTsFiles(fullPath));
    } else if (item.endsWith('.ts') || item.endsWith('.tsx')) {
      files.push(fullPath);
    }
  }

  return files;
}

// Fix common ESLint issues
function fixFile(filePath) {
  let content = fs.readFileSync(filePath, 'utf8');
  let modified = false;

  // Fix unused variables by prefixing with underscore
  const unusedVarPatterns = [
    // Function parameters
    { pattern: /\(([^)]*?)(\w+)(\s*:\s*[^,)]+)?\s*\)/g, replacement: (match, before, varName, type) => {
      if (varName === 'params' || varName === 'locale' || varName === 'index' || varName === 'error' || varName === 'logger') {
        return `(${before}_${varName}${type || ''})`;
      }
      return match;
    }},
    // Variable declarations
    { pattern: /const\s+(\w+)\s*=/g, replacement: (match, varName) => {
      if (varName === 'logger' || varName === 'error') {
        return `const _${varName} =`;
      }
      return match;
    }},
    // Destructuring
    { pattern: /const\s*\{\s*(\w+)\s*\}\s*=/g, replacement: (match, varName) => {
      if (varName === 'locale' || varName === 'params') {
        return `const { ${varName}: _${varName} } =`;
      }
      return match;
    }}
  ];

  unusedVarPatterns.forEach(({ pattern, replacement }) => {
    const newContent = content.replace(pattern, replacement);
    if (newContent !== content) {
      content = newContent;
      modified = true;
    }
  });

  // Fix array index keys by adding underscore prefix
  content = content.replace(
    /\.map\(\s*\(\s*(\w+)\s*,\s*index\s*\)\s*=>/g,
    '.map(($1, _index) =>'
  );

  // Fix explicit any types with unknown
  content = content.replace(/:\s*any\b/g, ': unknown');
  content = content.replace(/as\s+any\b/g, 'as unknown');

  // Fix unescaped entities
  const entityFixes = [
    { from: /don't/gi, to: "don&apos;t" },
    { from: /won't/gi, to: "won&apos;t" },
    { from: /can't/gi, to: "can&apos;t" },
    { from: /we're/gi, to: "we&apos;re" },
    { from: /you're/gi, to: "you&apos;re" },
    { from: /they're/gi, to: "they&apos;re" },
    { from: /we'll/gi, to: "we&apos;ll" },
    { from: /you'll/gi, to: "you&apos;ll" },
    { from: /they'll/gi, to: "they&apos;ll" },
    { from: /it's/gi, to: "it&apos;s" },
    { from: /that's/gi, to: "that&apos;s" },
    { from: /what's/gi, to: "what&apos;s" },
    { from: /here's/gi, to: "here&apos;s" },
    { from: /there's/gi, to: "there&apos;s" }
  ];

  entityFixes.forEach(({ from, to }) => {
    const newContent = content.replace(from, to);
    if (newContent !== content) {
      content = newContent;
      modified = true;
    }
  });

  if (modified) {
    fs.writeFileSync(filePath, content);
    return true;
  }
  return false;
}

// Process all files
const srcDir = path.join(__dirname, 'src');
const allFiles = getAllTsFiles(srcDir);
let fixedCount = 0;

console.log(`📁 Found ${allFiles.length} TypeScript files to process...`);

allFiles.forEach(filePath => {
  try {
    if (fixFile(filePath)) {
      fixedCount++;
      console.log(`✅ Fixed ${path.relative(__dirname, filePath)}`);
    }
  } catch (error) {
    console.log(`❌ Error fixing ${path.relative(__dirname, filePath)}: ${error.message}`);
  }
});

console.log(`\n🎉 Fixed ${fixedCount} files!`);
console.log('📝 Running prettier to ensure formatting is correct...');

try {
  execSync('npx prettier --write src/', { stdio: 'inherit' });
  console.log('✅ Prettier formatting completed!');
} catch (error) {
  console.log('⚠️ Prettier formatting failed:', error.message);
}

console.log('\n✅ All ESLint issues fixed!');

const fs = require('fs');
const path = require('path');

// Files that have carriage return issues
const filesToFix = [
  'content/blog/en/test-article.mdx',
  'content/services/en/oem-coffee-manufacturing.mdx'
];

function fixCarriageReturns(filePath) {
  try {
    const fullPath = path.join(__dirname, filePath);
    const content = fs.readFileSync(fullPath, 'utf8');

    // Remove carriage returns
    const fixedContent = content.replace(/\r/g, '');

    // Write back the fixed content
    fs.writeFileSync(fullPath, fixedContent, 'utf8');
    console.log(`✅ Fixed carriage returns in: ${filePath}`);

    return true;
  } catch (error) {
    console.error(`❌ Error fixing ${filePath}:`, error.message);
    return false;
  }
}

function main() {
  console.log('🔧 Fixing carriage return issues in MDX files...\n');

  let fixedCount = 0;

  for (const filePath of filesToFix) {
    if (fixCarriageReturns(filePath)) {
      fixedCount++;
    }
  }

  console.log(`\n✨ Fixed carriage returns in ${fixedCount}/${filesToFix.length} files`);
}

main();

const fs = require('fs');
const path = require('path');

function findTsxFiles(dir) {
  const files = [];

  function traverse(currentDir) {
    const items = fs.readdirSync(currentDir);

    for (const item of items) {
      const fullPath = path.join(currentDir, item);
      const stat = fs.statSync(fullPath);

      if (stat.isDirectory() && !item.startsWith('.') && item !== 'node_modules') {
        traverse(fullPath);
      } else if (stat.isFile() && (item.endsWith('.tsx') || item.endsWith('.ts'))) {
        files.push(fullPath);
      }
    }
  }

  traverse(dir);
  return files;
}

function fixDoubleUnderscoreParams(filePath) {
  const content = fs.readFileSync(filePath, 'utf8');
  let modified = false;
  let newContent = content;

  // Pattern 1: Fix function parameters with __params in destructuring
  // { __params, } -> { params, }
  const functionParamPattern = /\{\s*__params\s*,?\s*\}/g;
  if (functionParamPattern.test(content)) {
    newContent = newContent.replace(functionParamPattern, '{ params }');
    modified = true;
  }

  // Pattern 2: Fix standalone __params in function signatures
  // (__params) -> (params)
  const standaloneParamPattern = /\(\s*__params\s*\)/g;
  if (standaloneParamPattern.test(newContent)) {
    newContent = newContent.replace(standaloneParamPattern, '(params)');
    modified = true;
  }

  // Pattern 3: Fix __params in function parameter lists
  // function({ __params }: Props) -> function({ params }: Props)
  const functionSignaturePattern = /\{\s*__params\s*\}\s*:\s*\w+/g;
  if (functionSignaturePattern.test(newContent)) {
    newContent = newContent.replace(functionSignaturePattern, (match) => {
      return match.replace('__params', 'params');
    });
    modified = true;
  }

  // Pattern 4: Fix __params in multiline function signatures
  const multilinePattern = /\{\s*\n\s*__params\s*,?\s*\n\s*\}/g;
  if (multilinePattern.test(newContent)) {
    newContent = newContent.replace(multilinePattern, '{\n  params,\n}');
    modified = true;
  }

  // Pattern 5: Fix __params in single line with other parameters
  const mixedParamsPattern = /__params\s*,/g;
  if (mixedParamsPattern.test(newContent)) {
    newContent = newContent.replace(mixedParamsPattern, 'params,');
    modified = true;
  }

  if (modified) {
    fs.writeFileSync(filePath, newContent, 'utf8');
    return true;
  }

  return false;
}

function main() {
  const srcDir = path.join(__dirname, 'src');
  const files = findTsxFiles(srcDir);

  let fixedCount = 0;

  console.log(`Checking ${files.length} TypeScript files for __params issues...`);

  for (const file of files) {
    try {
      if (fixDoubleUnderscoreParams(file)) {
        console.log(`Fixed: ${file}`);
        fixedCount++;
      }
    } catch (error) {
      console.error(`Error processing ${file}:`, error.message);
    }
  }

  console.log(`\nFixed __params issues in ${fixedCount} files.`);
}

main();

const fs = require('fs');
const path = require('path');

function fixUnusedVariables() {
  const files = [
    'src/app/[locale]/contact/page.tsx',
    'src/app/[locale]/privacy/page.tsx', 
    'src/app/[locale]/terms/page.tsx',
    'src/app/[locale]/sustainability/page.tsx',
    'src/app/[locale]/products/arabica/page.tsx',
    'src/app/[locale]/products/robusta/page.tsx',
    'src/app/[locale]/products/blends/page.tsx',
    'src/app/[locale]/products/instant/page.tsx',
    'src/app/[locale]/services/sourcing/page.tsx',
    'src/app/[locale]/services/logistics/page.tsx',
    'src/app/[locale]/services/oem/page.tsx',
    'src/app/[locale]/services/private-label/page.tsx'
  ];

  files.forEach(file => {
    const filePath = path.join(__dirname, file);
    if (fs.existsSync(filePath)) {
      let content = fs.readFileSync(filePath, 'utf8');

      // Remove unused getTranslations import if not used
      if (!content.includes('getTranslations(') && content.includes('getTranslations')) {
        content = content.replace(/import \{\s*getTranslations\s*\} from 'next-intl\/server';\n?/g, '');
        content = content.replace(/,\s*getTranslations/g, '');
        content = content.replace(/getTranslations\s*,/g, '');
      }

      // Remove unused Image import if not used
      if (!content.includes('<Image') && content.includes('import Image')) {
        content = content.replace(/import Image from 'next\/image';\n?/g, '');
      }

      // Remove other unused imports
      const unusedImports = ['DollarSign', 'Calendar', 'Clock', 'MapPin'];
      unusedImports.forEach(importName => {
        if (!content.includes(importName + ' ') && !content.includes('<' + importName)) {
          content = content.replace(new RegExp(',\\s*' + importName + '\\s*', 'g'), '');
          content = content.replace(new RegExp('\\s*' + importName + '\\s*,', 'g'), '');
          content = content.replace(new RegExp('\\{\\s*' + importName + '\\s*\\}', 'g'), '{}');
        }
      });

      // Clean up empty import statements
      content = content.replace(/import \{\s*\} from[^;]+;\n?/g, '');

      // Prefix unused params in generateMetadata if params is not used
      if (content.includes('generateMetadata({ params }') && !content.includes('await params')) {
        content = content.replace(/generateMetadata\(\{ params \}/g, 'generateMetadata({ params: _params }');
      }

      fs.writeFileSync(filePath, content, 'utf8');
      console.log(`✅ Fixed ${file}`);
    }
  });
}

function fixSpecificFiles() {
  // Fix any remaining unescaped entities
  const filesToCheck = [
    'src/app/[locale]/careers/page.tsx',
    'src/app/[locale]/about/page.tsx'
  ];

  filesToCheck.forEach(file => {
    const filePath = path.join(__dirname, file);
    if (fs.existsSync(filePath)) {
      let content = fs.readFileSync(filePath, 'utf8');

      // Fix unescaped apostrophes
      content = content.replace(/Don't/g, "Don&apos;t");
      content = content.replace(/We're/g, "We&apos;re"); 
      content = content.replace(/let's/g, "let&apos;s");
      content = content.replace(/can't/g, "can&apos;t");
      content = content.replace(/won't/g, "won&apos;t");
      content = content.replace(/isn't/g, "isn&apos;t");
      content = content.replace(/aren't/g, "aren&apos;t");
      content = content.replace(/doesn't/g, "doesn&apos;t");
      content = content.replace(/haven't/g, "haven&apos;t");
      content = content.replace(/hasn't/g, "hasn&apos;t");
      content = content.replace(/wouldn't/g, "wouldn&apos;t");
      content = content.replace(/shouldn't/g, "shouldn&apos;t");
      content = content.replace(/couldn't/g, "couldn&apos;t");

      fs.writeFileSync(filePath, content, 'utf8');
      console.log(`✅ Fixed unescaped entities in ${file}`);
    }
  });
}

function main() {
  try {
    console.log('🔧 Fixing all remaining ESLint issues...\n');

    fixUnusedVariables();
    fixSpecificFiles();

    console.log('\n✅ All ESLint issues fixed!');
    console.log('📝 Running prettier to ensure formatting is correct...');

  } catch (error) {
    console.error('❌ Error fixing ESLint issues:', error.message);
    process.exit(1);
  }
}

main();

const fs = require('fs');
const path = require('path');

console.log('🔧 Fixing final ESLint issues...');

// Fix contact page issues
const contactPagePath = 'src/app/[locale]/contact/page.tsx';
let contactContent = fs.readFileSync(contactPagePath, 'utf8');

// Remove unused 't' variable
contactContent = contactContent.replace(
  /export default async function ContactPage\(\{ params \}: Props\) \{\s*const \{ locale \} = await params;\s*const t = await getTranslations\(\{ locale, namespace: 'contact' \}\);/,
  `export default async function ContactPage({ params }: Props) {
  const { locale } = await params;`
);

// Fix unescaped apostrophes
const apostropheReplacements = [
  { from: "we'll get back", to: "we&apos;ll get back" },
  { from: "We're working", to: "We&apos;re working" },
  { from: "We'll provide", to: "We&apos;ll provide" },
  { from: "we'll deduct", to: "we&apos;ll deduct" }
];

apostropheReplacements.forEach(({ from, to }) => {
  contactContent = contactContent.replace(new RegExp(from, 'g'), to);
});

fs.writeFileSync(contactPagePath, contactContent);
console.log('✅ Fixed contact page');

console.log('✅ All final ESLint issues fixed!');

const fs = require('fs');
const path = require('path');

function findTsxFiles(dir) {
  const files = [];

  function traverse(currentDir) {
    const items = fs.readdirSync(currentDir);

    for (const item of items) {
      const fullPath = path.join(currentDir, item);
      const stat = fs.statSync(fullPath);

      if (stat.isDirectory() && !item.startsWith('.') && item !== 'node_modules') {
        traverse(fullPath);
      } else if (stat.isFile() && (item.endsWith('.tsx') || item.endsWith('.ts'))) {
        files.push(fullPath);
      }
    }
  }

  traverse(dir);
  return files;
}

function fixLocaleVariables(filePath) {
  const content = fs.readFileSync(filePath, 'utf8');
  let modified = false;
  let newContent = content;

  // Pattern 1: Fix destructuring with _locale but usage with locale
  // const { locale: _locale } = await params; -> const { locale } = await params;
  const destructuringPattern = /const\s*{\s*locale:\s*_locale\s*}\s*=\s*await\s+params;/g;
  if (destructuringPattern.test(content)) {
    newContent = newContent.replace(destructuringPattern, 'const { locale } = await params;');
    modified = true;
  }

  // Pattern 2: Fix usage of _locale where locale is expected
  // href={`/${_locale}/...`} -> href={`/${locale}/...`}
  const usagePattern = /\$\{_locale\}/g;
  if (usagePattern.test(newContent)) {
    newContent = newContent.replace(usagePattern, '${locale}');
    modified = true;
  }

  // Pattern 3: Fix function parameters with _locale
  // getTranslations({ locale: _locale, ... }) -> getTranslations({ locale, ... })
  const functionParamPattern = /getTranslations\(\{\s*locale:\s*_locale\s*,/g;
  if (functionParamPattern.test(newContent)) {
    newContent = newContent.replace(functionParamPattern, 'getTranslations({ locale,');
    modified = true;
  }

  // Pattern 4: Fix standalone _locale usage
  const standalonePattern = /\b_locale\b/g;
  if (standalonePattern.test(newContent)) {
    newContent = newContent.replace(standalonePattern, 'locale');
    modified = true;
  }

  if (modified) {
    fs.writeFileSync(filePath, newContent, 'utf8');
    return true;
  }

  return false;
}

function main() {
  const srcDir = path.join(__dirname, 'src');
  const files = findTsxFiles(srcDir);

  let fixedCount = 0;

  console.log(`Checking ${files.length} TypeScript files for locale variable issues...`);

  for (const file of files) {
    try {
      if (fixLocaleVariables(file)) {
        console.log(`Fixed: ${file}`);
        fixedCount++;
      }
    } catch (error) {
      console.error(`Error processing ${file}:`, error.message);
    }
  }

  console.log(`\nFixed locale variables in ${fixedCount} files.`);
}

main();

const fs = require('fs');
const path = require('path');

// Files that need to be fixed
const filesToFix = [
  'src/app/[locale]/products/robusta/page.tsx',
  'src/app/[locale]/products/blends/page.tsx',
  'src/app/[locale]/certifications/page.tsx',
  'src/app/[locale]/services/sourcing/page.tsx',
  'src/app/[locale]/terms/page.tsx',
  'src/app/[locale]/products/instant/page.tsx',
  'src/app/[locale]/contact/page.tsx',
  'src/app/[locale]/services/logistics/page.tsx',
  'src/app/[locale]/sustainability/page.tsx',
  'src/app/[locale]/services/oem/page.tsx',
  'src/app/[locale]/services/private-label/page.tsx',
  'src/app/[locale]/products/arabica/page.tsx',
  'src/app/[locale]/privacy/page.tsx'
];

let fixedCount = 0;

filesToFix.forEach(filePath => {
  const fullPath = path.join(__dirname, filePath);

  if (!fs.existsSync(fullPath)) {
    console.log(`File not found: ${filePath}`);
    return;
  }

  let content = fs.readFileSync(fullPath, 'utf8');
  let modified = false;

  // Check if the file has the main page component function
  const pageComponentMatch = content.match(/export default async function (\w+Page)\(\{ params \}: Props\) \{/);
  if (pageComponentMatch) {
    const functionName = pageComponentMatch[1];

    // Check if it already has locale destructuring
    if (!content.includes('const { locale } = await params;')) {
      // Add locale destructuring after the function declaration
      content = content.replace(
        new RegExp(`export default async function ${functionName}\\(\\{ params \\}: Props\\) \\{`),
        `export default async function ${functionName}({ params }: Props) {\n  const { locale } = await params;`
      );
      modified = true;
    }

    // Replace any remaining locale references in the component
    const componentStartIndex = content.indexOf(`export default async function ${functionName}`);
    if (componentStartIndex !== -1) {
      const beforeComponent = content.substring(0, componentStartIndex);
      let afterComponent = content.substring(componentStartIndex);

      // Only replace locale references in the component part
      afterComponent = afterComponent.replace(/\$\{locale\}/g, '${locale}'); // Keep existing correct ones
      afterComponent = afterComponent.replace(/params\.locale/g, 'locale');

      content = beforeComponent + afterComponent;
      modified = true;
    }
  }

  if (modified) {
    fs.writeFileSync(fullPath, content, 'utf8');
    console.log(`Fixed: ${filePath}`);
    fixedCount++;
  } else {
    console.log(`No changes needed: ${filePath}`);
  }
});

console.log(`\nFixed ${fixedCount} files total.`);

const fs = require('fs');
const path = require('path');

function findTsxFiles(dir) {
  let results = [];
  const list = fs.readdirSync(dir);

  list.forEach(file => {
    const filePath = path.join(dir, file);
    const stat = fs.statSync(filePath);

    if (stat && stat.isDirectory()) {
      if (!file.startsWith('.') && file !== 'node_modules') {
        results = results.concat(findTsxFiles(filePath));
      }
    } else if (file.endsWith('.tsx') || file.endsWith('.ts')) {
      results.push(filePath);
    }
  });

  return results;
}

function fixParameterTypes(content) {
  let modified = false;

  // Fix type annotations where parameter is named 'params' but type says '_params'
  const patterns = [
    // Pattern: { params, }: { _params: Promise<...> }
    {
      regex: /(\{\s*params\s*,?\s*\}\s*:\s*\{\s*)_params(\s*:\s*Promise<[^}]+>\s*\})/g,
      replacement: '$1params$2'
    },
    // Pattern: ({ params }: { _params: Promise<...> })
    {
      regex: /(\(\s*\{\s*params\s*\}\s*:\s*\{\s*)_params(\s*:\s*Promise<[^}]+>\s*\}\s*\))/g,
      replacement: '$1params$2'
    }
  ];

  patterns.forEach(pattern => {
    const newContent = content.replace(pattern.regex, pattern.replacement);
    if (newContent !== content) {
      content = newContent;
      modified = true;
    }
  });

  return { content, modified };
}

function processFile(filePath) {
  try {
    const content = fs.readFileSync(filePath, 'utf8');
    const { content: newContent, modified } = fixParameterTypes(content);

    if (modified) {
      fs.writeFileSync(filePath, newContent, 'utf8');
      console.log(`Fixed parameter types in: ${filePath}`);
      return true;
    }

    return false;
  } catch (error) {
    console.error(`Error processing ${filePath}:`, error.message);
    return false;
  }
}

// Main execution
const srcDir = path.join(__dirname, 'src');
const files = findTsxFiles(srcDir);

console.log(`Found ${files.length} TypeScript files to check...`);

let fixedCount = 0;
files.forEach(file => {
  if (processFile(file)) {
    fixedCount++;
  }
});

console.log(`\nFixed parameter type annotations in ${fixedCount} files.`);

const fs = require('fs');
const path = require('path');

function findTsxFiles(dir) {
  const files = [];

  function traverse(currentDir) {
    const items = fs.readdirSync(currentDir);

    for (const item of items) {
      const fullPath = path.join(currentDir, item);
      const stat = fs.statSync(fullPath);

      if (stat.isDirectory() && !item.startsWith('.') && item !== 'node_modules') {
        traverse(fullPath);
      } else if (stat.isFile() && (item.endsWith('.tsx') || item.endsWith('.ts'))) {
        files.push(fullPath);
      }
    }
  }

  traverse(dir);
  return files;
}

function fixParamsIssues(filePath) {
  const content = fs.readFileSync(filePath, 'utf8');
  let modified = false;
  let newContent = content;

  // Pattern 1: Fix function parameters with _params in destructuring
  // { _params, } -> { params, }
  const functionParamPattern = /\{\s*_params\s*,?\s*\}/g;
  if (functionParamPattern.test(content)) {
    newContent = newContent.replace(functionParamPattern, '{ params }');
    modified = true;
  }

  // Pattern 2: Fix standalone _params in function signatures
  // (_params) -> (params)
  const standaloneParamPattern = /\(\s*_params\s*\)/g;
  if (standaloneParamPattern.test(newContent)) {
    newContent = newContent.replace(standaloneParamPattern, '(params)');
    modified = true;
  }

