    // Pattern: function({ _params }: { _params: Promise<...> })
    const functionParamPattern = /\(\s*\{\s*_params\s*\}:\s*\{\s*params:/g;
    if (functionParamPattern.test(content)) {
      content = content.replace(functionParamPattern, '({ params }: { params:');
