                  <SelectItem value="expired">{t('status.expired')}</SelectItem>
                  <SelectItem value="pending">{t('status.pending')}</SelectItem>
                  <SelectItem value="archived">
                    {t('status.archived')}
                  </SelectItem>
                </SelectContent>
              </Select>

              <Select value={sortBy} onValueChange={setSortBy}>
                <SelectTrigger className="w-full lg:w-48">
                  <SelectValue placeholder={t('sortBy')} />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="uploadDate">
                    {t('sortOptions.uploadDate')}
                  </SelectItem>
                  <SelectItem value="name">{t('sortOptions.name')}</SelectItem>
                  <SelectItem value="type">{t('sortOptions.type')}</SelectItem>
                  <SelectItem value="size">{t('sortOptions.size')}</SelectItem>
                </SelectContent>
              </Select>
            </div>
          </CardContent>
        </Card>

        {/* Documents Table */}
        <Card>
          <CardHeader>
            <CardTitle>{t('documentsTable.title')}</CardTitle>
            <CardDescription>
              {t('documentsTable.description', {
                count: filteredDocuments.length,
              })}
            </CardDescription>
          </CardHeader>
          <CardContent>
            {filteredDocuments.length === 0 ? (
              <div className="py-12 text-center">
                <FileText className="mx-auto mb-4 h-12 w-12 text-gray-400" />
                <p className="mb-2 text-gray-600">{t('noDocuments')}</p>
                <p className="text-sm text-gray-500">
                  {t('noDocumentsDescription')}
                </p>
              </div>
            ) : (
              <Table>
                <TableHeader>
                  <TableRow>
                    <TableHead>{t('tableHeaders.document')}</TableHead>
                    <TableHead>{t('tableHeaders.type')}</TableHead>
                    <TableHead>{t('tableHeaders.status')}</TableHead>
                    <TableHead>{t('tableHeaders.uploadDate')}</TableHead>
                    <TableHead>{t('tableHeaders.expiryDate')}</TableHead>
                    <TableHead>{t('tableHeaders.size')}</TableHead>
                    <TableHead>{t('tableHeaders.actions')}</TableHead>
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {filteredDocuments.map(document => (
                    <TableRow key={document.id}>
                      <TableCell>
                        <div className="flex items-center gap-3">
                          {getDocumentIcon(document.type)}
                          <div className="min-w-0 flex-1">
                            <div className="flex items-center gap-2">
                              <p className="truncate font-medium">
                                {document.name}
                              </p>
                              <Button
                                variant="ghost"
                                size="sm"
                                onClick={() => toggleFavorite(document.id)}
                                className="h-6 w-6 p-0"
                              >
                                {document.isFavorite ? (
                                  <Star className="h-4 w-4 fill-current text-yellow-500" />
                                ) : (
                                  <StarOff className="h-4 w-4 text-gray-400" />
                                )}
                              </Button>
                            </div>
                            {document.description && (
                              <p className="truncate text-sm text-gray-600">
                                {document.description}
                              </p>
                            )}
                            {document.tags.length > 0 && (
                              <div className="mt-1 flex gap-1">
                                {document.tags.slice(0, 2).map(tag => (
                                  <Badge
                                    key={tag}
                                    variant="outline"
                                    className="text-xs"
                                  >
                                    {tag}
                                  </Badge>
                                ))}
                                {document.tags.length > 2 && (
                                  <Badge variant="outline" className="text-xs">
                                    +{document.tags.length - 2}
                                  </Badge>
                                )}
                              </div>
                            )}
                          </div>
                        </div>
                      </TableCell>
                      <TableCell>
                        <Badge variant="outline">
                          {t(`types.${document.type}`)}
                        </Badge>
                      </TableCell>
                      <TableCell>
                        <div className="flex items-center gap-2">
                          {getStatusBadge(document.status)}
                          {document.expiryDate &&
                            isExpiringThisMonth(document.expiryDate) && (
                              <AlertTriangle className="h-4 w-4 text-orange-500" />
                            )}
                        </div>
                      </TableCell>
                      <TableCell className="text-sm text-gray-600">
                        {formatDate(document.uploadDate)}
                      </TableCell>
                      <TableCell className="text-sm text-gray-600">
                        {document.expiryDate
                          ? formatDate(document.expiryDate)
                          : '-'}
                      </TableCell>
                      <TableCell className="text-sm text-gray-600">
                        {formatFileSize(document.size)}
                      </TableCell>
                      <TableCell>
                        <DropdownMenu>
                          <DropdownMenuTrigger asChild>
                            <Button variant="ghost" size="sm">
                              {t('actions')}
                            </Button>
                          </DropdownMenuTrigger>
                          <DropdownMenuContent align="end">
                            <DropdownMenuItem>
                              <Eye className="mr-2 h-4 w-4" />
                              {t('view')}
                            </DropdownMenuItem>
                            <DropdownMenuItem>
                              <Download className="mr-2 h-4 w-4" />
                              {t('download')}
                            </DropdownMenuItem>
                            <DropdownMenuItem>
                              <Share className="mr-2 h-4 w-4" />
                              {t('share')}
                            </DropdownMenuItem>
                            <DropdownMenuItem>
                              <Edit className="mr-2 h-4 w-4" />
                              {t('edit')}
                            </DropdownMenuItem>
                            <DropdownMenuSeparator />
                            <DropdownMenuItem className="text-red-600">
                              <Trash2 className="mr-2 h-4 w-4" />
                              {t('delete')}
                            </DropdownMenuItem>
                          </DropdownMenuContent>
                        </DropdownMenu>
                      </TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            )}
          </CardContent>
        </Card>
      </ContentSection>
    </ContentContainer>
  );
}

