// Mapping functions to convert API strings to design system types
const mapApiGradeToDesignGrade = (apiGrade: string): CoffeeGrade => {
  const gradeMap: Record<string, CoffeeGrade> = {
    'GRADE_1': 'grade-1',
    'GRADE_2': 'grade-2',
    'GRADE_3': 'grade-3',
    'PREMIUM': 'premium',
    'SPECIALTY': 'specialty',
    'SCREEN_18': 'screen-18',
    'SCREEN_16': 'screen-16',
    'SCREEN_14': 'screen-14',
    'EXCHANGE': 'exchange',
    'STANDARD': 'standard',
    'COMMERCIAL': 'standard',
  };
  return gradeMap[apiGrade] || 'standard';
};

const mapApiProcessingToDesignProcessing = (apiProcessing: string): ProcessingMethod => {
  const processingMap: Record<string, ProcessingMethod> = {
    'NATURAL': 'natural',
    'WASHED': 'washed',
    'HONEY': 'honey',
    'WET_HULLED': 'wet-hulled',
    'SEMI_WASHED': 'semi-washed',
    'MIXED': 'natural', // fallback
  };
  return processingMap[apiProcessing] || 'natural';
};

