// POST /api/products/bulk - Bulk operations (pricing updates, inventory sync, etc.)
export async function POST(request: NextRequest) {
  try {
    const body = await request.json();
    const { operation } = body;

    switch (operation) {
      case 'updatePricing':
        return await handleBulkPricingUpdate(body);
      case 'syncInventory':
        return await handleBulkInventorySync(body);
      case 'updateCertifications':
        return await handleBulkCertificationUpdate(body);
      default:
        return NextResponse.json(
          {
            success: false,
            error: 'Invalid operation',
            supportedOperations: [
              'updatePricing',
              'syncInventory',
              'updateCertifications',
            ],
          },
          { status: 400 }
        );
    }
  } catch (_error) {
    // Error logging removed for production
    return NextResponse.json(
      {
        success: false,
        error: 'Failed to perform bulk operation',
        details: _error instanceof Error ? _error.message : 'Unknown error',
      },
      { status: 500 }
    );
  }
}

async function handleBulkPricingUpdate(body: unknown) {
  const { productIds, pricingUpdates, updatedBy } =
    BulkPricingUpdateSchema.parse(body);

  const results = await Promise.allSettled(
    productIds.map(async productId => {
      const pricing = pricingUpdates[productId];
      if (!pricing) return null;

      return await prisma.coffeeProduct.update({
        where: { id: productId },
        data: convertUndefinedToNull({
          pricing,
          updatedBy,
          updatedAt: new Date(),
        }),
      });
    })
  );

  const successful = results.filter(r => r.status === 'fulfilled').length;
  const failed = results.filter(r => r.status === 'rejected').length;

  return NextResponse.json({
    success: true,
    message: `Pricing update completed: ${successful} successful, ${failed} failed`,
    data: {
      successful,
      failed,
      total: productIds.length,
    },
  });
}

async function handleBulkInventorySync(body: unknown) {
  const {
    productIds,
    inventoryData,
    updatedBy: _updatedBy,
  } = z
    .object({
      productIds: z.array(z.string()),
      inventoryData: z.record(
        z.string(),
        z.object({
          quantity: z.number(),
          unit: z.string(),
          location: z.string().optional(),
          reservedQuantity: z.number().optional(),
        })
      ),
      updatedBy: z.string(),
    })
    .parse(body);

  const results = await Promise.allSettled(
    productIds.map(async productId => {
      const inventory = inventoryData[productId];
      if (!inventory) return null;

      // Find existing inventory record
      const existingInventory = await prisma.productInventory.findFirst({
        where: { productId },
      });

      if (existingInventory) {
        // Update existing record
        return await prisma.productInventory.update({
          where: { id: existingInventory.id },
          data: convertUndefinedToNull({
            ...inventory,
            lastUpdated: new Date(),
          }),
        });
      } else {
        // Create new record
        return await prisma.productInventory.create({
          data: convertUndefinedToNull({
            productId,
            ...inventory,
            lastUpdated: new Date(),
          }) as any,
        });
      }
    })
  );

  const successful = results.filter(r => r.status === 'fulfilled').length;
  const failed = results.filter(r => r.status === 'rejected').length;

  return NextResponse.json({
    success: true,
    message: `Inventory sync completed: ${successful} successful, ${failed} failed`,
    data: {
      successful,
      failed,
      total: productIds.length,
    },
  });
}

async function handleBulkCertificationUpdate(body: unknown) {
  const {
    productIds,
    certificationIds,
    action,
    updatedBy: _updatedBy,
  } = z
    .object({
      productIds: z.array(z.string()),
      certificationIds: z.array(z.string()),
      action: z.enum(['add', 'remove']),
      updatedBy: z.string(),
    })
    .parse(body);

  const results = await Promise.allSettled(
    productIds.map(async productId => {
      if (action === 'add') {
        return await Promise.all(
          certificationIds.map(certId =>
            prisma.productCertification.upsert({
              where: {
                productId_certificationId: {
                  productId,
                  certificationId: certId,
                },
              },
              update: convertUndefinedToNull({
                isActive: true,
              }) as any,
              create: convertUndefinedToNull({
                productId,
                certificationId: certId,
                isActive: true,
              }) as any,
            })
          )
        );
      } else {
        return await prisma.productCertification.updateMany({
          where: {
            productId,
            certificationId: {
              in: certificationIds,
            },
          },
          data: {
            isActive: false,
          },
        });
      }
    })
  );

  const successful = results.filter(r => r.status === 'fulfilled').length;
  const failed = results.filter(r => r.status === 'rejected').length;

  return NextResponse.json({
    success: true,
    message: `Certification update completed: ${successful} successful, ${failed} failed`,
    data: {
      successful,
      failed,
      total: productIds.length,
    },
  });
}

import { NextRequest, NextResponse } from 'next/server';
import { PrismaClient } from '@prisma/client';
import { z } from 'zod';

const prisma = new PrismaClient();

// Utility function to convert undefined to null for Prisma compatibility
function convertUndefinedToNull<T extends Record<string, any>>(
  obj: T
): Record<string, any> {
  const result: Record<string, any> = {};
  for (const key in obj) {
    if (obj[key] === undefined) {
      result[key] = null;
    } else {
      result[key] = obj[key];
    }
  }
  return result;
}

// Validation schemas
const ProductFilterSchema = z.object({
  page: z.string().optional().default('1'),
  limit: z.string().optional().default('20'),
  search: z.string().optional(),
  coffeeType: z.enum(['ROBUSTA', 'ARABICA', 'BLEND', 'SPECIALTY']).optional(),
  grade: z
    .enum(['GRADE_1', 'GRADE_2', 'GRADE_3', 'PREMIUM', 'SPECIALTY', 'CUSTOM'])
    .optional(),
  processing: z
    .enum(['NATURAL', 'WASHED', 'HONEY', 'WET_HULLED', 'SEMI_WASHED', 'MIXED'])
    .optional(),
  origin: z.string().optional(),
  region: z.string().optional(),
  minCuppingScore: z.string().optional(),
  maxCuppingScore: z.string().optional(),
  certifications: z.string().optional(), // Comma-separated certification IDs
  inStock: z.string().optional(),
  isFeatured: z.string().optional(),
  sortBy: z
    .enum(['name', 'cuppingScore', 'createdAt', 'updatedAt', 'origin'])
    .optional()
    .default('createdAt'),
  sortOrder: z.enum(['asc', 'desc']).optional().default('desc'),
  locale: z.string().optional().default('en'),
});

const CreateProductSchema = z.object({
  sku: z.string().min(1),
  coffeeType: z.enum(['ROBUSTA', 'ARABICA', 'BLEND', 'SPECIALTY']),
  grade: z.enum([
    'GRADE_1',
    'GRADE_2',
    'GRADE_3',
    'PREMIUM',
    'SPECIALTY',
    'CUSTOM',
  ]),
  processing: z.enum([
    'NATURAL',
    'WASHED',
    'HONEY',
    'WET_HULLED',
    'SEMI_WASHED',
    'MIXED',
  ]),
  origin: z.string().min(1),
  region: z.string().optional(),
  farm: z.string().optional(),
  altitude: z.string().optional(),
  harvestSeason: z.string().optional(),
  cuppingScore: z.number().min(0).max(100).optional(),
  moisture: z.string().optional(),
  screenSize: z.string().optional(),
  defectRate: z.string().optional(),
  leadTime: z.string().optional(),
  minimumOrder: z.string().optional(),
  specifications: z.record(z.string(), z.any()).optional(),
  pricing: z.record(z.string(), z.any()).optional(),
  availability: z.record(z.string(), z.any()).optional(),
  originInfo: z.record(z.string(), z.any()).optional(),
  features: z.array(z.string()).optional(),
  images: z.array(z.string()).optional(),
  documents: z.array(z.string()).optional(),
  isActive: z.boolean().optional().default(true),
  isFeatured: z.boolean().optional().default(false),
  createdBy: z.string().min(1),
});

// GET /api/products - List products with filtering and search
export async function GET(request: NextRequest) {
  try {
    const { searchParams } = new URL(request.url);
    const params = Object.fromEntries(searchParams.entries());

    const {
      page,
      limit,
      search,
      coffeeType,
      grade,
      processing,
      origin,
      region,
      minCuppingScore,
      maxCuppingScore,
      certifications,
      inStock,
      isFeatured,
      sortBy,
      sortOrder,
      locale: locale,
    } = ProductFilterSchema.parse(params);

    const pageNum = parseInt(page);
    const limitNum = parseInt(limit);
    const skip = (pageNum - 1) * limitNum;

    // Build where clause
    const where: any = {
      isActive: true,
    };

    if (search) {
      where.OR = [
        {
          translations: {
            some: {
              locale,
              OR: [
                { name: { contains: search, mode: 'insensitive' } },
                { description: { contains: search, mode: 'insensitive' } },
                { tastingNotes: { contains: search, mode: 'insensitive' } },
              ],
            },
          },
        },
        { sku: { contains: search, mode: 'insensitive' } },
        { origin: { contains: search, mode: 'insensitive' } },
        { region: { contains: search, mode: 'insensitive' } },
        { farm: { contains: search, mode: 'insensitive' } },
      ];
    }

    if (coffeeType) where.coffeeType = coffeeType;
    if (grade) where.grade = grade;
    if (processing) where.processing = processing;
    if (origin) where.origin = { contains: origin, mode: 'insensitive' };
    if (region) where.region = { contains: region, mode: 'insensitive' };
    if (inStock === 'true') where.inStock = true;
    if (isFeatured === 'true') where.isFeatured = true;

    // Cupping score range
    if (minCuppingScore || maxCuppingScore) {
      where.cuppingScore = {};
      if (minCuppingScore) where.cuppingScore.gte = parseFloat(minCuppingScore);
      if (maxCuppingScore) where.cuppingScore.lte = parseFloat(maxCuppingScore);
    }

    // Certifications filter
    if (certifications) {
      const certIds = certifications.split(',');
      where.certifications = {
        some: {
          certificationId: { in: certIds },
          isActive: true,
        },
      };
    }

    // Build orderBy
    const orderBy: any = {};
    if (sortBy === 'name') {
      orderBy.translations = {
        _count: 'desc',
      };
    } else {
      orderBy[sortBy] = sortOrder;
    }

    // Execute query
    const [products, total] = await Promise.all([
      prisma.coffeeProduct.findMany({
        where,
        include: {
          translations: {
            where: { locale },
          },
          certifications: {
            where: { isActive: true },
            include: {
              certification: {
                include: {
                  translations: {
                    where: { locale },
                  },
                },
              },
            },
          },
          suppliers: {
            where: { isActive: true },
            include: {
              supplier: {
                select: {
                  id: true,
                  name: true,
                  country: true,
                  qualityRating: true,
                },
              },
            },
          },
          inventory: {
            select: {
              currentStock: true,
              availableStock: true,
              unit: true,
            },
          },
          pricingModels: {
            where: { isActive: true },
            include: {
              pricingModel: {
                select: {
                  id: true,
                  name: true,
                  type: true,
                  basePrice: true,
                  currency: true,
                  unit: true,
                },
              },
            },
          },
        },
        orderBy,
        skip,
        take: limitNum,
      }),
      prisma.coffeeProduct.count({ where }),
    ]);

    const totalPages = Math.ceil(total / limitNum);

    return NextResponse.json({
      success: true,
      data: {
        products,
        pagination: {
          page: pageNum,
          limit: limitNum,
          total,
          totalPages,
          hasNext: pageNum < totalPages,
          hasPrev: pageNum > 1,
        },
      },
    });
  } catch (_error) {
    return NextResponse.json(
      {
        success: false,
        error: 'Failed to fetch products',
        details: _error instanceof Error ? _error.message : 'Unknown error',
      },
      { status: 500 }
    );
  }
}

// POST /api/products - Create new product
export async function POST(request: NextRequest) {
  try {
    const body = await request.json();
    const validatedData = CreateProductSchema.parse(body);

    const product = await prisma.coffeeProduct.create({
      data: convertUndefinedToNull({
        ...validatedData,
        updatedBy: validatedData.createdBy,
      }) as any,
      include: {
        translations: true,
        certifications: {
          include: {
            certification: true,
          },
        },
        // suppliers: {
        //   include: {
        //     supplier: true,
        //   },
        // },
      },
    });

    return NextResponse.json(
      {
        success: true,
        data: product,
      },
      { status: 201 }
    );
  } catch (_error) {
    if (_error instanceof z.ZodError) {
      return NextResponse.json(
        {
          success: false,
          error: 'Validation error',
          details: _error.issues,
        },
        { status: 400 }
      );
    }

    return NextResponse.json(
      {
        success: false,
        error: 'Failed to create product',
        details: _error instanceof Error ? _error.message : 'Unknown error',
      },
      { status: 500 }
    );
  }
}

