// POST /api/products/search - Advanced product search
export async function POST(request: NextRequest) {
  try {
    const body = await request.json();
    const {
      q,
      coffeeType,
      grade,
      processing,
      origin,
      region,
      cuppingScoreMin,
      cuppingScoreMax,
      certifications,
      inStock,
      isFeatured,
      priceMin: _priceMin,
      priceMax: _priceMax,
      sortBy,
      sortOrder,
      page,
      limit,
      locale: locale,
    } = SearchProductsSchema.parse(body);

    const skip = (page - 1) * limit;

    // Build where clause
    const where: any = {
      isActive: true,
    };

    // Text search
    if (q) {
      where.OR = [
        {
          sku: {
            contains: q,
            mode: 'insensitive',
          },
        },
        {
          origin: {
            contains: q,
            mode: 'insensitive',
          },
        },
        {
          region: {
            contains: q,
            mode: 'insensitive',
          },
        },
        {
          farm: {
            contains: q,
            mode: 'insensitive',
          },
        },
        {
          translations: {
            some: {
              locale,
              OR: [
                {
                  name: {
                    contains: q,
                    mode: 'insensitive',
                  },
                },
                {
                  description: {
                    contains: q,
                    mode: 'insensitive',
                  },
                },
                {
                  flavorProfile: {
                    contains: q,
                    mode: 'insensitive',
                  },
                },
              ],
            },
          },
        },
      ];
    }

    // Filter by coffee type
    if (coffeeType && coffeeType.length > 0) {
      where.coffeeType = {
        in: coffeeType,
      };
    }

    // Filter by grade
    if (grade && grade.length > 0) {
      where.grade = {
        in: grade,
      };
    }

    // Filter by processing method
    if (processing && processing.length > 0) {
      where.processing = {
        in: processing,
      };
    }

    // Filter by origin
    if (origin && origin.length > 0) {
      where.origin = {
        in: origin,
      };
    }

    // Filter by region
    if (region && region.length > 0) {
      where.region = {
        in: region,
      };
    }

    // Filter by cupping score range
    if (cuppingScoreMin !== undefined || cuppingScoreMax !== undefined) {
      where.cuppingScore = {};
      if (cuppingScoreMin !== undefined) {
        where.cuppingScore.gte = cuppingScoreMin;
      }
      if (cuppingScoreMax !== undefined) {
