/**
 * Enhanced SEO Service for The Great Beans
 * Provides comprehensive SEO capabilities for the application layer including:
 * - Dynamic metadata generation
 * - Schema.org structured data management
 * - International SEO optimization
 * - Performance and Core Web Vitals optimization
 * - AI and voice search optimization
 */

export interface SEOPageData {
  // Page identification
  pageType:
    | 'home'
    | 'product'
    | 'service'
    | 'article'
    | 'collection'
    | 'about'
    | 'contact'
    | 'report'
    | 'origin-story';
  slug?: string;
  locale: Locale;

  // Content data
  title: string;
  description: string;
  keywords: string[];
  content?: string;

  // Media
  images?: Array<{
    url: string;
    alt: string;
    width?: number;
    height?: number;
    caption?: string;
  }>;

  // Dates
  publishedDate?: string;
  modifiedDate?: string;

  // Author and attribution
  author?: string;

  // Category and tags
  category?: string;
  tags?: string[];

  // Business data
  price?: {
    amount: string;
    currency: string;
    unit?: string;
  };
  availability?: 'InStock' | 'OutOfStock' | 'PreOrder' | 'Discontinued';

  // Navigation
  breadcrumbs?: Array<{ name: string; url: string }>;

  // Related content
  relatedItems?: Array<{ name: string; url: string; description?: string }>;

  // FAQ for AI optimization
  faqs?: Array<{ question: string; answer: string }>;

  // Custom properties
  customData?: Record<string, any>;
}

export interface SEOOptimizationOptions {
  // Performance optimization
  enableImageOptimization?: boolean;
  enableCriticalResourcePreload?: boolean;
  enableCoreWebVitalsTracking?: boolean;

  // Content optimization
  enableSchemaMarkup?: boolean;
  enableFAQOptimization?: boolean;
  enableBreadcrumbMarkup?: boolean;

  // International SEO
  enableHreflangTags?: boolean;
  alternateLocales?: Locale[];

  // Analytics and tracking
  enableAnalytics?: boolean;
  enableEnhancedEcommerce?: boolean;

  // Custom optimization
  customSchemas?: Record<string, any>[];
  preloadResources?: Array<{
    href: string;
    as: 'image' | 'font' | 'script' | 'style';
    type?: string;
    crossOrigin?: 'anonymous' | 'use-credentials';
  }>;
}

export interface SEOAuditResult {
  score: number;
  issues: Array<{
    type: 'error' | 'warning' | 'info';
    category:
      | 'metadata'
      | 'schema'
      | 'performance'
      | 'accessibility'
      | 'international';
    message: string;
    recommendation?: string;
  }>;
  recommendations: string[];
  performance: {
    metaTagsCount: number;
    schemaCount: number;
    imageOptimization: boolean;
    internationalSEO: boolean;
  };
}

