  /**
   * Perform comprehensive SEO audit
   */
  async auditPageSEO(
    pageData: SEOPageData,
    currentMetadata?: Metadata,
    currentSchemas?: Record<string, any>[]
  ): Promise<SEOAuditResult> {
    const issues: SEOAuditResult['issues'] = [];
    const recommendations: string[] = [];
    let score = 100;

    // Audit metadata
    if (!pageData.title || pageData.title.length < 30) {
      issues.push({
        type: 'warning',
        category: 'metadata',
        message: 'Title is too short (recommended: 30-60 characters)',
        recommendation: 'Expand title to include more descriptive keywords',
      });
      score -= 10;
    }

    if (pageData.title && pageData.title.length > 60) {
      issues.push({
        type: 'warning',
        category: 'metadata',
        message: 'Title is too long (recommended: 30-60 characters)',
        recommendation: 'Shorten title to improve search result display',
      });
      score -= 5;
    }

    if (!pageData.description || pageData.description.length < 120) {
      issues.push({
        type: 'warning',
        category: 'metadata',
        message: 'Description is too short (recommended: 120-160 characters)',
        recommendation: 'Expand description to provide more context',
      });
      score -= 10;
    }

    if (pageData.description && pageData.description.length > 160) {
      issues.push({
        type: 'warning',
        category: 'metadata',
        message: 'Description is too long (recommended: 120-160 characters)',
        recommendation:
          'Shorten description to prevent truncation in search results',
      });
      score -= 5;
    }

    if (!pageData.keywords || pageData.keywords.length < 3) {
      issues.push({
        type: 'warning',
        category: 'metadata',
        message: 'Insufficient keywords (recommended: 3-10 relevant keywords)',
        recommendation:
          'Add more relevant keywords for better content classification',
      });
      score -= 10;
    }

    // Audit images
    if (!pageData.images || pageData.images.length === 0) {
      issues.push({
        type: 'info',
        category: 'metadata',
        message: 'No images found for social sharing',
        recommendation:
          'Add at least one high-quality image for better social media sharing',
      });
      score -= 5;
    }

    // Audit structured data
    if (!currentSchemas || currentSchemas.length < 2) {
      issues.push({
        type: 'warning',
        category: 'schema',
        message: 'Insufficient structured data markup',
        recommendation:
          'Add more Schema.org markup for better search engine understanding',
      });
      score -= 15;
    }

    // Audit international SEO
    if (pageData.locale && !pageData.breadcrumbs) {
      issues.push({
        type: 'info',
        category: 'international',
        message: 'Missing breadcrumb navigation',
        recommendation:
          'Add breadcrumb navigation for better user experience and SEO',
      });
      score -= 5;
    }

    // Generate recommendations
    if (score < 80) {
      recommendations.push(
        'Focus on improving metadata quality and completeness'
      );
    }
    if (!currentSchemas || currentSchemas.length < 3) {
      recommendations.push(
        'Implement comprehensive Schema.org markup for better search visibility'
      );
    }
    if (!pageData.faqs && pageData.pageType === 'product') {
      recommendations.push(
        'Add FAQ section to optimize for voice search and AI assistants'
      );
    }

    return {
      score: Math.max(0, score),
      issues,
      recommendations,
      performance: {
        metaTagsCount: this.countMetaTags(currentMetadata),
        schemaCount: currentSchemas?.length || 0,
        imageOptimization: pageData.images?.every(img => img.alt) || false,
        internationalSEO: !!pageData.breadcrumbs,
      },
    };
  }

  /**
   * Generate sitemap entry for a page
   */
  generateSitemapEntry(
    pageData: SEOPageData,
    lastModified?: string
  ): {
    url: string;
    lastModified: string;
    changeFrequency: string;
    priority: number;
    images?: Array<{ url: string; caption?: string; title?: string }>;
  } {
    const sitemapEntry = {
      url: this.generateCanonicalUrl(pageData),
      lastModified:
        lastModified ||
        pageData.modifiedDate ||
        pageData.publishedDate ||
        new Date().toISOString(),
      changeFrequency: this.getChangeFrequency(pageData.pageType),
      priority: this.calculatePagePriority(pageData.pageType),
    };

    if (pageData.images && pageData.images.length > 0) {
      return {
        ...sitemapEntry,
        images: pageData.images.map(img => ({
          url: img.url.startsWith('http')
            ? img.url
            : `${this.baseUrl}${img.url}`,
          caption: img.caption || img.alt,
          title: img.alt,
        })),
      };
    }

    return sitemapEntry;
  }

  /**
   * Helper methods
   */
  private mapPageTypeToContentType(
    pageType: string
  ): AdvancedSEOMetadata['contentType'] {
    const mapping: Record<string, AdvancedSEOMetadata['contentType']> = {
      home: 'website',
      product: 'product',
      service: 'service',
      article: 'article',
      collection: 'collection',
      about: 'organization',
      contact: 'organization',
      report: 'article',
      'origin-story': 'article',
    };

    return mapping[pageType] || 'website';
  }

  private generateCanonicalUrl(pageData: SEOPageData): string {
    const basePath = `${this.baseUrl}/${pageData.locale}`;

    if (pageData.pageType === 'home') {
      return basePath;
    }

    const typeMapping = {
      product: 'products',
      service: 'services',
      article: 'blog',
      report: 'market-reports',
      'origin-story': 'origins',
      collection: pageData.slug || 'collection',
    };

    const pathSegment =
      typeMapping[pageData.pageType as keyof typeof typeMapping] ||
      pageData.pageType;

    return pageData.slug
      ? `${basePath}/${pathSegment}/${pageData.slug}`
      : `${basePath}/${pathSegment}`;
  }

  private calculatePagePriority(pageType: string): number {
    const priorities = {
      home: 1.0,
      product: 0.8,
      service: 0.8,
      collection: 0.7,
      article: 0.6,
      report: 0.7,
      'origin-story': 0.6,
      about: 0.5,
      contact: 0.5,
    };

    return priorities[pageType as keyof typeof priorities] || 0.5;
  }

  private getChangeFrequency(
    pageType: string
  ): 'always' | 'hourly' | 'daily' | 'weekly' | 'monthly' | 'yearly' | 'never' {
    const frequencies = {
      home: 'weekly',
      product: 'monthly',
      service: 'monthly',
      collection: 'weekly',
      article: 'never',
      report: 'monthly',
      'origin-story': 'yearly',
      about: 'yearly',
      contact: 'yearly',
    };

    return (frequencies[pageType as keyof typeof frequencies] || 'monthly') as
      | 'always'
      | 'hourly'
      | 'daily'
      | 'weekly'
      | 'monthly'
      | 'yearly'
      | 'never';
  }

  private async addPageSpecificSchemas(
    pageData: SEOPageData,
    schemas: Record<string, any>[]
  ): Promise<void> {
    // This method can be extended to add more specific schemas based on page content
    // For now, it&apos;s a placeholder for future enhancements
  }

  private generatePreloadResources(
    pageData: SEOPageData,
    options: SEOOptimizationOptions
  ): Array<{ href: string; as: string; type?: string; crossOrigin?: string }> {
    const resources: Array<{
      href: string;
      as: string;
      type?: string;
      crossOrigin?: string;
    }> = [];

    // Add custom preload resources
    if (options.preloadResources) {
      resources.push(...options.preloadResources);
    }

    // Add critical image preloading
    if (options.enableImageOptimization !== false && pageData.images?.[0]) {
      const primaryImage = pageData.images[0];
      if (primaryImage.url) {
        resources.push({
          href: primaryImage.url.startsWith('http')
            ? primaryImage.url
            : `${this.baseUrl}${primaryImage.url}`,
          as: 'image',
        });
      }
    }

    // Add font preloading
    if (options.enableCriticalResourcePreload !== false) {
      resources.push(
        {
          href: 'https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&display=swap',
          as: 'style',
        },
        {
          href: 'https://fonts.gstatic.com/s/inter/v12/UcCO3FwrK3iLTeHuS_fvQtMwCp50KnMw2boKoduKmMEVuLyfAZ9hiJ-Ek-_EeA.woff2',
          as: 'font',
          type: 'font/woff2',
          crossOrigin: 'anonymous',
        }
      );
    }

    return resources;
  }

  private countMetaTags(metadata?: Metadata): number {
    if (!metadata) return 0;

    let count = 0;
    if (metadata.title) count++;
    if (metadata.description) count++;
    if (metadata.keywords) count++;
    if (metadata.openGraph) count += Object.keys(metadata.openGraph).length;
    if (metadata.twitter) count += Object.keys(metadata.twitter).length;

    return count;
  }

  private mapAvailabilityToSEOFormat(
    availability: unknown
  ): 'InStock' | 'OutOfStock' | 'PreOrder' | 'Discontinued' {
    if (typeof availability === 'string') {
      const normalizedAvailability = availability.toLowerCase();
      if (
        normalizedAvailability.includes('stock') ||
        normalizedAvailability === 'available'
      ) {
        return 'InStock';
      }
      if (
        normalizedAvailability.includes('out') ||
        normalizedAvailability === 'unavailable'
      ) {
        return 'OutOfStock';
      }
      if (
        normalizedAvailability.includes('preorder') ||
        normalizedAvailability.includes('pre-order')
      ) {
        return 'PreOrder';
      }
      if (normalizedAvailability.includes('discontinued')) {
        return 'Discontinued';
      }
    }

    // Default fallback
    return 'InStock';
  }
}

