// Types for inventory management
interface InventoryItem {
  id: string;
  productId: string;
  productName: string;
  sku: string;
  category: string;
  currentStock: number;
  reservedStock: number;
  availableStock: number;
  reorderPoint: number;
  maxStock: number;
  unit: string;
  costPerUnit: number;
  totalValue: number;
  location: string;
  supplier: string;
  lastRestocked: string;
  expiryDate?: string;
  qualityGrade: 'A' | 'B' | 'C';
  status: 'in_stock' | 'low_stock' | 'out_of_stock' | 'expired' | 'reserved';
  movementHistory: InventoryMovement[];
  forecastData: ForecastData;
}

interface InventoryMovement {
  id: string;
  type: 'in' | 'out' | 'adjustment' | 'transfer' | 'reserved' | 'released';
  quantity: number;
  reason: string;
  reference?: string;
  timestamp: string;
  user: string;
  notes?: string;
}

interface ForecastData {
  demandForecast: number;
  leadTime: number;
  safetyStock: number;
  reorderQuantity: number;
  nextReorderDate: string;
  confidence: number;
}

interface InventoryAlert {
  id: string;
  type:
    | 'low_stock'
    | 'out_of_stock'
    | 'expiring'
    | 'overstock'
    | 'quality_issue';
  productId: string;
  productName: string;
  message: string;
  severity: 'low' | 'medium' | 'high' | 'critical';
  timestamp: string;
  acknowledged: boolean;
}

interface InventoryManagerProps {
  className?: string;
}

