export function InventoryManager({ className }: InventoryManagerProps) {
  const [inventoryItems, setInventoryItems] =
    useState<InventoryItem[]>(mockInventoryItems);
  const [alerts, setAlerts] = useState<InventoryAlert[]>(mockAlerts);
  const [searchTerm, setSearchTerm] = useState('');
  const [statusFilter, setStatusFilter] = useState<string>('all');
  const [categoryFilter, setCategoryFilter] = useState<string>('all');
  const [selectedItem, setSelectedItem] = useState<InventoryItem | null>(null);
  const [isMovementDialogOpen, setIsMovementDialogOpen] = useState(false);
  const [isReorderDialogOpen, setIsReorderDialogOpen] = useState(false);

  // Filter inventory items
  const filteredItems = inventoryItems.filter(item => {
    const matchesSearch =
      item.productName.toLowerCase().includes(searchTerm.toLowerCase()) ||
      item.sku.toLowerCase().includes(searchTerm.toLowerCase());
    const matchesStatus =
      statusFilter === 'all' || item.status === statusFilter;
    const matchesCategory =
      categoryFilter === 'all' || item.category === categoryFilter;

    return matchesSearch && matchesStatus && matchesCategory;
  });

  // Calculate summary statistics
  const totalValue = inventoryItems.reduce(
    (sum, item) => sum + item.totalValue,
    0
  );
  const lowStockItems = inventoryItems.filter(
    item => item.status === 'low_stock'
  ).length;
  const outOfStockItems = inventoryItems.filter(
    item => item.status === 'out_of_stock'
  ).length;
  const unacknowledgedAlerts = alerts.filter(
    alert => !alert.acknowledged
  ).length;

  const getStatusBadge = (status: string) => {
    const statusConfig = {
      in_stock: {
        label: 'In Stock',
        variant: 'default' as const,
        icon: CheckCircle,
      },
      low_stock: {
        label: 'Low Stock',
        variant: 'destructive' as const,
        icon: AlertTriangle,
      },
      out_of_stock: {
        label: 'Out of Stock',
        variant: 'destructive' as const,
        icon: AlertTriangle,
      },
      expired: {
        label: 'Expired',
        variant: 'destructive' as const,
        icon: Clock,
      },
      reserved: {
        label: 'Reserved',
        variant: 'secondary' as const,
        icon: Archive,
      },
    };

    const config = statusConfig[status as keyof typeof statusConfig];
    if (!config) return null;

    const Icon = config.icon;
    return (
      <Badge variant={config.variant} className="flex items-center gap-1">
        <Icon className="h-3 w-3" />
        {config.label}
      </Badge>
    );
  };

  const getAlertSeverityBadge = (severity: string) => {
    const severityConfig = {
      low: { label: 'Low', variant: 'secondary' as const },
      medium: { label: 'Medium', variant: 'default' as const },
      high: { label: 'High', variant: 'destructive' as const },
      critical: { label: 'Critical', variant: 'destructive' as const },
    };

    const config = severityConfig[severity as keyof typeof severityConfig];
    return config ? (
      <Badge variant={config.variant}>{config.label}</Badge>
    ) : null;
  };

  const handleAcknowledgeAlert = (alertId: string) => {
    setAlerts(prev =>
      prev.map(alert =>
        alert.id === alertId ? { ...alert, acknowledged: true } : alert
      )
    );
  };

