                  <SelectContent>
                    <SelectItem value="all">All Categories</SelectItem>
                    <SelectItem value="Arabica">Arabica</SelectItem>
                    <SelectItem value="Robusta">Robusta</SelectItem>
                    <SelectItem value="Specialty">Specialty</SelectItem>
                  </SelectContent>
                </Select>
              </div>
            </CardContent>
          </Card>

          {/* Inventory Table */}
          <Card>
            <CardHeader>
              <CardTitle>Inventory Items</CardTitle>
              <CardDescription>
                Manage your coffee inventory and track stock levels
              </CardDescription>
            </CardHeader>
            <CardContent>
              <Table>
                <TableHeader>
                  <TableRow>
                    <TableHead>Product</TableHead>
                    <TableHead>SKU</TableHead>
                    <TableHead>Category</TableHead>
                    <TableHead>Current Stock</TableHead>
                    <TableHead>Available</TableHead>
                    <TableHead>Status</TableHead>
                    <TableHead>Value</TableHead>
                    <TableHead>Location</TableHead>
                    <TableHead>Actions</TableHead>
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {filteredItems.map(item => (
                    <TableRow key={item.id}>
                      <TableCell>
                        <div>
                          <p className="font-medium">{item.productName}</p>
                          <p className="text-sm text-coffee-600">
                            Grade {item.qualityGrade}
                          </p>
                        </div>
                      </TableCell>
                      <TableCell className="font-mono text-sm">
                        {item.sku}
                      </TableCell>
                      <TableCell>{item.category}</TableCell>
                      <TableCell>
                        <div>
                          <p className="font-medium">
                            {item.currentStock.toLocaleString()} {item.unit}
                          </p>
                          <Progress
                            value={(item.currentStock / item.maxStock) * 100}
                            className="mt-1 h-2 w-16"
                          />
                        </div>
                      </TableCell>
                      <TableCell>
                        {item.availableStock.toLocaleString()} {item.unit}
                      </TableCell>
                      <TableCell>{getStatusBadge(item.status)}</TableCell>
                      <TableCell>${item.totalValue.toLocaleString()}</TableCell>
                      <TableCell>{item.location}</TableCell>
                      <TableCell>
                        <div className="flex gap-1">
                          <Button
                            variant="ghost"
                            size="sm"
                            onClick={() => setSelectedItem(item)}
                          >
                            <Eye className="h-4 w-4" />
                          </Button>
                          <Button
                            variant="ghost"
                            size="sm"
                            onClick={() => {
                              setSelectedItem(item);
                              setIsMovementDialogOpen(true);
                            }}
                          >
                            <Edit className="h-4 w-4" />
                          </Button>
                          <Button
                            variant="ghost"
                            size="sm"
                            onClick={() => {
                              setSelectedItem(item);
                              setIsReorderDialogOpen(true);
                            }}
                          >
                            <ShoppingCart className="h-4 w-4" />
                          </Button>
                        </div>
                      </TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            </CardContent>
          </Card>
        </TabsContent>

        {/* Alerts Tab */}
        <TabsContent value="alerts" className="space-y-4">
          <Card>
            <CardHeader>
              <CardTitle>Inventory Alerts</CardTitle>
              <CardDescription>
                Monitor and manage inventory alerts and notifications
              </CardDescription>
            </CardHeader>
            <CardContent>
              <div className="space-y-4">
                {alerts.map(alert => (
                  <div
                    key={alert.id}
                    className={`rounded-lg border p-4 ${
                      alert.acknowledged
                        ? 'border-gray-200 bg-gray-50'
                        : 'border-red-200 bg-red-50'
                    }`}
                  >
                    <div className="flex items-center justify-between">
                      <div className="flex items-center gap-3">
                        <AlertTriangle
                          className={`h-5 w-5 ${
                            alert.severity === 'critical'
                              ? 'text-red-600'
                              : alert.severity === 'high'
                                ? 'text-orange-600'
                                : 'text-yellow-600'
                          }`}
                        />
                        <div>
                          <p className="font-medium">{alert.productName}</p>
                          <p className="text-sm text-coffee-600">
                            {alert.message}
                          </p>
                          <p className="text-xs text-coffee-500">
                            {new Date(alert.timestamp).toLocaleString()}
                          </p>
                        </div>
                      </div>
                      <div className="flex items-center gap-2">
                        {getAlertSeverityBadge(alert.severity)}
                        {!alert.acknowledged && (
                          <Button
                            variant="outline"
                            size="sm"
                            onClick={() => handleAcknowledgeAlert(alert.id)}
                          >
                            Acknowledge
                          </Button>
                        )}
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            </CardContent>
          </Card>
        </TabsContent>

        {/* Forecasting Tab */}
        <TabsContent value="forecasting" className="space-y-4">
          <div className="grid grid-cols-1 gap-6 lg:grid-cols-2">
            {inventoryItems.map(item => (
              <Card key={item.id}>
                <CardHeader>
                  <CardTitle className="text-lg">{item.productName}</CardTitle>
                  <CardDescription>
                    Demand forecasting and reorder planning
                  </CardDescription>
                </CardHeader>
                <CardContent className="space-y-4">
                  <div className="grid grid-cols-2 gap-4">
                    <div>
                      <Label className="text-sm font-medium">
                        Forecast Demand
                      </Label>
                      <p className="text-lg font-semibold text-coffee-800">
                        {item.forecastData.demandForecast} {item.unit}/month
                      </p>
                    </div>
                    <div>
                      <Label className="text-sm font-medium">Confidence</Label>
                      <p className="text-lg font-semibold text-green-600">
                        {item.forecastData.confidence}%
                      </p>
                    </div>
                    <div>
                      <Label className="text-sm font-medium">Lead Time</Label>
                      <p className="text-lg font-semibold text-coffee-800">
                        {item.forecastData.leadTime} days
                      </p>
                    </div>
                    <div>
                      <Label className="text-sm font-medium">
                        Safety Stock
                      </Label>
                      <p className="text-lg font-semibold text-coffee-800">
                        {item.forecastData.safetyStock} {item.unit}
                      </p>
                    </div>
                  </div>
                  <div className="border-t pt-2">
                    <div className="flex items-center justify-between">
                      <div>
                        <Label className="text-sm font-medium">
                          Next Reorder
                        </Label>
                        <p className="text-sm text-coffee-600">
                          {new Date(
                            item.forecastData.nextReorderDate
                          ).toLocaleDateString()}
                        </p>
                      </div>
                      <Button variant="outline" size="sm">
                        <Target className="mr-2 h-4 w-4" />
                        Adjust Forecast
                      </Button>
                    </div>
                  </div>
                </CardContent>
              </Card>
            ))}
          </div>
        </TabsContent>

        {/* Reports Tab */}
        <TabsContent value="reports" className="space-y-4">
          <div className="grid grid-cols-1 gap-4 md:grid-cols-2 lg:grid-cols-3">
            <Card className="cursor-pointer transition-shadow hover:shadow-md">
              <CardContent className="p-6">
                <div className="flex items-center gap-3">
                  <BarChart3 className="h-8 w-8 text-blue-500" />
                  <div>
                    <h3 className="font-semibold">Stock Level Report</h3>
                    <p className="text-sm text-coffee-600">
                      Current stock levels and trends
                    </p>
                  </div>
                </div>
              </CardContent>
            </Card>

            <Card className="cursor-pointer transition-shadow hover:shadow-md">
              <CardContent className="p-6">
                <div className="flex items-center gap-3">
                  <Activity className="h-8 w-8 text-green-500" />
                  <div>
                    <h3 className="font-semibold">Movement History</h3>
                    <p className="text-sm text-coffee-600">
                      Inventory movements and transactions
                    </p>
                  </div>
                </div>
              </CardContent>
            </Card>

            <Card className="cursor-pointer transition-shadow hover:shadow-md">
              <CardContent className="p-6">
                <div className="flex items-center gap-3">
                  <TrendingUp className="h-8 w-8 text-purple-500" />
                  <div>
                    <h3 className="font-semibold">Demand Analysis</h3>
                    <p className="text-sm text-coffee-600">
                      Demand patterns and forecasting
                    </p>
                  </div>
                </div>
              </CardContent>
            </Card>

            <Card className="cursor-pointer transition-shadow hover:shadow-md">
              <CardContent className="p-6">
                <div className="flex items-center gap-3">
                  <DollarSign className="h-8 w-8 text-gold-500" />
                  <div>
                    <h3 className="font-semibold">Valuation Report</h3>
                    <p className="text-sm text-coffee-600">
                      Inventory value and cost analysis
                    </p>
                  </div>
                </div>
              </CardContent>
            </Card>

            <Card className="cursor-pointer transition-shadow hover:shadow-md">
              <CardContent className="p-6">
                <div className="flex items-center gap-3">
                  <Truck className="h-8 w-8 text-orange-500" />
