// Types for pricing management
interface PricingTier {
  id: string;
  name: string;
  minQuantity: number;
  maxQuantity?: number;
  discountPercentage: number;
  pricePerUnit: number;
}

interface PricingRule {
  id: string;
  name: string;
  type:
    | 'volume'
    | 'customer_tier'
    | 'seasonal'
    | 'market_based'
    | 'promotional';
  conditions: Record<string, any>;
  action: 'discount' | 'markup' | 'fixed_price';
  value: number;
  isActive: boolean;
  validFrom: string;
  validTo?: string;
  priority: number;
}

interface ProductPricing {
  id: string;
  productId: string;
  productName: string;
  sku: string;
  category: string;
  baseCost: number;
  basePrice: number;
  currentPrice: number;
  margin: number;
  marginPercentage: number;
  currency: string;
  lastUpdated: string;
  pricingTiers: PricingTier[];
  appliedRules: string[];
  competitorPrices: CompetitorPrice[];
  priceHistory: PriceHistoryEntry[];
  status: 'active' | 'inactive' | 'pending_approval';
  marketPosition: 'premium' | 'competitive' | 'value';
}

interface CompetitorPrice {
  id: string;
  competitor: string;
  price: number;
  currency: string;
  lastChecked: string;
  source: string;
}

interface PriceHistoryEntry {
  id: string;
  price: number;
  reason: string;
  changedBy: string;
  timestamp: string;
  appliedRules?: string[];
}

interface MarketAnalysis {
  productId: string;
  averageMarketPrice: number;
  priceRange: {
    min: number;
    max: number;
  };
  ourPosition: number; // percentile
  recommendation: 'increase' | 'decrease' | 'maintain';
  confidence: number;
  factors: string[];
}

interface PricingManagerProps {
  className?: string;
}

