export function ProductEditor({
  product,
  isOpen,
  onClose,
  onSave,
  mode,
}: ProductEditorProps) {
  const [formData, setFormData] = useState<ProductData>(defaultProduct);
  const [activeTab, setActiveTab] = useState('basic');
  const [isSaving, setIsSaving] = useState(false);
  const [newFlavorNote, setNewFlavorNote] = useState('');
  const [newTag, setNewTag] = useState('');

  useEffect(() => {
    if (product) {
      setFormData(product);
    } else {
      setFormData(defaultProduct);
    }
  }, [product]);

  const handleInputChange = (field: keyof ProductData, value: unknown) => {
    setFormData(prev => ({
      ...prev,
      [field]: value,
    }));
  };

  const generateSlug = (name: string) => {
    return name
      .toLowerCase()
      .replace(/[^a-z0-9]+/g, '-')
      .replace(/(^-|-$)/g, '');
  };

  const handleNameChange = (name: string) => {
    handleInputChange('name', name);
    if (mode === 'create') {
      handleInputChange('slug', generateSlug(name));
      handleInputChange('metaTitle', name);
    }
  };

  const addFlavorNote = () => {
    if (newFlavorNote && !formData.flavorNotes.includes(newFlavorNote)) {
      handleInputChange('flavorNotes', [
        ...formData.flavorNotes,
        newFlavorNote,
      ]);
      setNewFlavorNote('');
    }
  };

  const removeFlavorNote = (note: string) => {
    handleInputChange(
      'flavorNotes',
      formData.flavorNotes.filter(n => n !== note)
    );
  };

  const addTag = () => {
    if (newTag && !formData.tags.includes(newTag)) {
      handleInputChange('tags', [...formData.tags, newTag]);
      setNewTag('');
    }
  };

  const removeTag = (tag: string) => {
    handleInputChange(
      'tags',
      formData.tags.filter(t => t !== tag)
    );
  };

  const handleSave = async () => {
    setIsSaving(true);
    try {
      await onSave(formData);
      onClose();
    } catch (_error) {
      // Error handling removed for production
    } finally {
      setIsSaving(false);
    }
  };

  const ScaleInput = ({
    label,
    value,
    onChange,
    min = 1,
    max = 10,
  }: {
    label: string;
    value: number;
    onChange: (value: number) => void;
    min?: number;
    max?: number;
  }) => (
    <div className="space-y-2">
      <Label>{label}</Label>
      <div className="flex items-center gap-2">
        <Button
          type="button"
          variant="outline"
          size="sm"
          onClick={() => onChange(Math.max(min, value - 1))}
          disabled={value <= min}
        >
          <Minus className="h-3 w-3" />
        </Button>
        <div className="flex-1 text-center font-medium">
          {value}/{max}
        </div>
        <Button
          type="button"
          variant="outline"
          size="sm"
          onClick={() => onChange(Math.min(max, value + 1))}
          disabled={value >= max}
        >
          <Plus className="h-3 w-3" />
        </Button>
      </div>
      <div className="h-2 rounded-full bg-gray-200">
        <div
          className="h-2 rounded-full bg-coffee-500 transition-all"
          style={{ width: `${(value / max) * 100}%` }}
        />
      </div>
    </div>
  );

  return (
    <Dialog open={isOpen} onOpenChange={onClose}>
      <DialogContent className="max-h-[90vh] max-w-6xl overflow-hidden">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            <Coffee className="h-5 w-5" />
            {mode === 'create' ? 'Create New Product' : 'Edit Product'}
          </DialogTitle>
          <DialogDescription>
            {mode === 'create'
              ? 'Add a new coffee product to your catalog'
              : 'Update product information, pricing, and inventory'}
          </DialogDescription>
        </DialogHeader>

        <div className="flex-1 overflow-hidden">
          <Tabs
            value={activeTab}
            onValueChange={setActiveTab}
            className="h-full"
