                    <Coffee className="h-12 w-12 text-muted-foreground" />
                  </div>
                )}
              </div>
              <CardTitle className="line-clamp-2 text-sm">
                {product.name}
              </CardTitle>
              <div className="flex items-center gap-2">
                <Badge variant="outline" className="text-xs">
                  {product.origin}
                </Badge>
                <div className="flex items-center gap-1">
                  <Star className="h-3 w-3 fill-yellow-400 text-yellow-400" />
                  <span className="text-xs">{product.rating}</span>
                </div>
              </div>
            </CardHeader>
            <CardContent className="pt-0">
              <div className="space-y-2">
                <div className="font-semibold">
                  ${product.price.toFixed(2)}/{product.unit}
                </div>
                <div className="flex gap-1">
                  <Button
                    size="sm"
                    className="flex-1"
                    onClick={() => onProductSelect(product.id)}
                  >
                    <Eye className="mr-1 h-3 w-3" />
                    View
                  </Button>
                  <Button size="sm" variant="outline">
                    <ShoppingCart className="h-3 w-3" />
                  </Button>
                  <Button size="sm" variant="outline">
                    <Heart className="h-3 w-3" />
                  </Button>
                </div>
              </div>
            </CardContent>
          </Card>
        ))}
      </div>

      {/* Detailed Comparison */}
      <Card>
        <CardHeader>
          <CardTitle>Detailed Comparison</CardTitle>
          <CardDescription>
            Compare detailed specifications and characteristics
          </CardDescription>
        </CardHeader>
        <CardContent>
          <Tabs value={activeCategory} onValueChange={setActiveCategory}>
            <TabsList className="grid w-full grid-cols-5">
              {comparisonCategories.map(category => {
                const Icon = category.icon;
                return (
                  <TabsTrigger
                    key={category.id}
                    value={category.id}
                    className="flex items-center gap-2"
                  >
                    <Icon className="h-4 w-4" />
                    <span className="hidden sm:inline">{category.label}</span>
                  </TabsTrigger>
                );
              })}
            </TabsList>

            {comparisonCategories.map(category => (
              <TabsContent
                key={category.id}
                value={category.id}
                className="mt-6"
              >
                {viewMode === 'grid' ? (
                  <div className="space-y-4">
                    {category.fields.map(field => {
                      const hasDifferences =
                        highlightDifferences && getFieldDifferences(field);
                      return (
                        <div key={field.key} className="space-y-2">
                          <div className="flex items-center gap-2">
                            <Label className="font-medium">{field.label}</Label>
                            {hasDifferences && (
                              <Badge variant="outline" className="text-xs">
                                Different
                              </Badge>
                            )}
                          </div>
                          <div
                            className="grid gap-4"
                            style={{
                              gridTemplateColumns: `repeat(${products.length}, 1fr)`,
                            }}
                          >
                            {products.map(product => (
                              <div
                                key={product.id}
                                className="rounded-lg border p-3"
                              >
                                {renderFieldValue(
                                  product,
                                  field,
                                  hasDifferences
                                )}
                              </div>
                            ))}
                          </div>
                        </div>
                      );
                    })}
                  </div>
                ) : (
                  <Table>
                    <TableHeader>
                      <TableRow>
                        <TableHead>Specification</TableHead>
                        {products.map(product => (
                          <TableHead key={product.id} className="text-center">
                            {product.name}
                          </TableHead>
                        ))}
                      </TableRow>
                    </TableHeader>
                    <TableBody>
                      {category.fields.map(field => {
                        const hasDifferences =
                          highlightDifferences && getFieldDifferences(field);
                        return (
                          <TableRow key={field.key}>
                            <TableCell className="font-medium">
                              <div className="flex items-center gap-2">
                                {field.label}
                                {hasDifferences && (
                                  <Badge variant="outline" className="text-xs">
                                    Different
                                  </Badge>
                                )}
                              </div>
                            </TableCell>
                            {products.map(product => (
                              <TableCell
                                key={product.id}
                                className="text-center"
                              >
                                {renderFieldValue(
                                  product,
                                  field,
                                  hasDifferences
                                )}
                              </TableCell>
                            ))}
                          </TableRow>
                        );
                      })}
                    </TableBody>
                  </Table>
                )}
              </TabsContent>
            ))}
          </Tabs>
        </CardContent>
      </Card>
    </div>
  );
}

'use client';

import { useState, useCallback, useEffect } from 'react';
import {
  ChevronLeft,
  ChevronRight,
  ZoomIn,
  Download,
  Share2,
  Coffee,
} from 'lucide-react';

import { EnhancedProductImage } from '@/shared/components/performance/EnhancedOptimizedImage';
import { Button } from '@/presentation/components/ui/button';
import { Card, CardContent } from '@/presentation/components/ui/card';
import { Badge } from '@/presentation/components/ui/badge';
import { cn } from '@/lib/utils';

export interface ProductImage {
  id: string;
  url: string;
  cloudinaryId?: string;
  alt: string;
  caption?: string;
  isPrimary?: boolean;
  category?: 'product' | 'packaging' | 'origin' | 'process' | 'quality';
}

interface ProductImageGalleryProps {
  images: ProductImage[];
  productName: string;
  className?: string;
  showThumbnails?: boolean;
  showControls?: boolean;
  showImageInfo?: boolean;
  enableZoom?: boolean;
  enableDownload?: boolean;
  enableShare?: boolean;
}

const imageCategoryLabels = {
  product: 'Product',
  packaging: 'Packaging',
  origin: 'Origin',
  process: 'Processing',
  quality: 'Quality Control',
};

const imageCategoryColors = {
  product: 'bg-coffee-500',
  packaging: 'bg-amber-500',
  origin: 'bg-green-500',
  process: 'bg-blue-500',
  quality: 'bg-purple-500',
};

export function ProductImageGallery({
  images,
  productName,
  className,
  showThumbnails = true,
  showControls = true,
  showImageInfo = true,
  enableZoom = true,
  enableDownload = false,
  enableShare = false,
}: ProductImageGalleryProps) {
  const [currentImageIndex, setCurrentImageIndex] = useState(0);
  const [isZoomed, setIsZoomed] = useState(false);
  const [isLoading, setIsLoading] = useState(true);

  // Find primary image or use first image
  const primaryImageIndex = images.findIndex(img => img.isPrimary) || 0;

  useEffect(() => {
    setCurrentImageIndex(primaryImageIndex);
  }, [primaryImageIndex]);

  const currentImage = images[currentImageIndex];
  const hasMultipleImages = images.length > 1;

  // Early return if no images or current image
  if (!images.length || !currentImage) {
    return (
      <Card className={cn('overflow-hidden', className)}>
        <CardContent className="p-6">
          <div className="flex h-80 w-full items-center justify-center rounded-lg bg-gradient-to-br from-coffee-100 to-coffee-200">
            <div className="text-center">
              <Coffee className="mx-auto h-24 w-24 text-coffee-400" />
              <p className="mt-4 text-sm text-coffee-600">
                No images available
              </p>
            </div>
          </div>
        </CardContent>
      </Card>
    );
  }

  const goToPrevious = useCallback(() => {
    setCurrentImageIndex(prev => (prev === 0 ? images.length - 1 : prev - 1));
  }, [images.length]);

  const goToNext = useCallback(() => {
    setCurrentImageIndex(prev => (prev === images.length - 1 ? 0 : prev + 1));
  }, [images.length]);

  const handleThumbnailClick = useCallback((_index: number) => {
    setCurrentImageIndex(_index);
  }, []);

  const handleZoomToggle = useCallback(() => {
    setIsZoomed(prev => !prev);
  }, []);

  const handleDownload = useCallback(async () => {
    if (!currentImage || !enableDownload) return;

    try {
      const response = await fetch(currentImage.url);
      const blob = await response.blob();
      const url = window.URL.createObjectURL(blob);
      const link = document.createElement('a');
      link.href = url;
      link.download = `${productName}-${currentImage.id}.jpg`;
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
      window.URL.revokeObjectURL(url);
    } catch (_error) {
      // Download error handling removed for production
    }
  }, [currentImage, productName, enableDownload]);

  const handleShare = useCallback(async () => {
    if (!currentImage || !enableShare) return;

    if (navigator.share) {
      try {
        await navigator.share({
          title: `${productName} - ${currentImage.alt}`,
          text: `Check out this ${productName} image`,
          url: currentImage.url,
        });
      } catch (_error) {
        // Share error handling removed for production
      }
    } else {
      // Fallback: copy to clipboard
      try {
        await navigator.clipboard.writeText(currentImage.url);
        // You could show a toast notification here
      } catch (_error) {
        // Clipboard error handling removed for production
      }
    }
  }, [currentImage, productName, enableShare]);

  // Keyboard navigation
  useEffect(() => {
    const handleKeyDown = (event: KeyboardEvent) => {
      if (event.key === 'ArrowLeft') {
        goToPrevious();
      } else if (event.key === 'ArrowRight') {
        goToNext();
      } else if (event.key === 'Escape') {
        setIsZoomed(false);
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [goToPrevious, goToNext]);

  if (!images.length) {
    return (
      <Card className={cn('overflow-hidden', className)}>
        <CardContent className="p-6">
          <div className="flex h-80 w-full items-center justify-center rounded-lg bg-gradient-to-br from-coffee-100 to-coffee-200">
            <div className="text-center">
              <Coffee className="mx-auto h-24 w-24 text-coffee-400" />
              <p className="mt-4 text-sm text-coffee-600">
                No images available
              </p>
            </div>
          </div>
        </CardContent>
      </Card>
    );
  }

  return (
    <Card className={cn('overflow-hidden', className)}>
      <CardContent className="p-6">
        {/* Main Image Display */}
        <div className="relative mb-4">
          <div
            className={cn(
              'relative overflow-hidden rounded-lg bg-gradient-to-br from-coffee-50 to-coffee-100',
              isZoomed ? 'h-96' : 'h-80',
              'transition-all duration-300'
            )}
          >
            {currentImage.cloudinaryId ? (
              <EnhancedProductImage
                publicId={currentImage.cloudinaryId}
                alt={currentImage.alt}
                size="large"
                className={cn(
                  'h-full w-full object-cover transition-transform duration-300',
                  isZoomed && 'scale-110 cursor-zoom-out',
                  !isZoomed && enableZoom && 'cursor-zoom-in'
                )}
                onClick={enableZoom ? handleZoomToggle : undefined}
                priority={currentImageIndex === 0}
                onLoadComplete={() => setIsLoading(false)}
              />
            ) : (
              <div className="flex h-full w-full items-center justify-center">
                <Coffee className="h-24 w-24 text-coffee-400" />
              </div>
            )}

            {/* Loading Overlay */}
            {isLoading && (
              <div className="absolute inset-0 flex items-center justify-center bg-coffee-100/80">
                <div className="h-8 w-8 animate-spin rounded-full border-2 border-coffee-500 border-t-transparent" />
              </div>
            )}

            {/* Navigation Controls */}
            {showControls && hasMultipleImages && (
              <>
                <Button
                  variant="outline"
                  size="icon"
                  className="absolute left-2 top-1/2 -translate-y-1/2 bg-white/90 hover:bg-white"
                  onClick={goToPrevious}
                  aria-label="Previous image"
                >
                  <ChevronLeft className="h-4 w-4" />
                </Button>
                <Button
                  variant="outline"
                  size="icon"
                  className="absolute right-2 top-1/2 -translate-y-1/2 bg-white/90 hover:bg-white"
                  onClick={goToNext}
                  aria-label="Next image"
                >
                  <ChevronRight className="h-4 w-4" />
                </Button>
              </>
            )}

            {/* Action Controls */}
            <div className="absolute right-2 top-2 flex gap-2">
              {enableZoom && (
                <Button
                  variant="outline"
                  size="icon"
                  className="bg-white/90 hover:bg-white"
                  onClick={handleZoomToggle}
                  aria-label={isZoomed ? 'Zoom out' : 'Zoom in'}
                >
                  <ZoomIn className="h-4 w-4" />
                </Button>
              )}
              {enableDownload && (
                <Button
                  variant="outline"
                  size="icon"
                  className="bg-white/90 hover:bg-white"
                  onClick={handleDownload}
                  aria-label="Download image"
                >
                  <Download className="h-4 w-4" />
                </Button>
              )}
              {enableShare && (
                <Button
                  variant="outline"
                  size="icon"
                  className="bg-white/90 hover:bg-white"
                  onClick={handleShare}
                  aria-label="Share image"
                >
                  <Share2 className="h-4 w-4" />
                </Button>
              )}
            </div>

            {/* Image Category Badge */}
            {showImageInfo && currentImage.category && (
              <div className="absolute bottom-2 left-2">
                <Badge
                  className={cn(
                    'text-white',
                    imageCategoryColors[currentImage.category]
                  )}
                >
                  {imageCategoryLabels[currentImage.category]}
                </Badge>
              </div>
            )}

            {/* Image Counter */}
            {hasMultipleImages && (
              <div className="absolute bottom-2 right-2">
                <Badge variant="secondary" className="bg-black/70 text-white">
                  {currentImageIndex + 1} / {images.length}
                </Badge>
              </div>
            )}
          </div>

          {/* Image Caption */}
          {showImageInfo && currentImage.caption && (
            <p className="mt-2 text-sm text-coffee-600">
              {currentImage.caption}
            </p>
          )}
        </div>

        {/* Thumbnail Gallery */}
        {showThumbnails && hasMultipleImages && (
          <div className="grid grid-cols-4 gap-2 sm:grid-cols-6">
            {images.map((image, _index) => (
              <button
                key={image.id}
                onClick={() => handleThumbnailClick(_index)}
                className={cn(
                  'relative h-16 w-full overflow-hidden rounded border-2 transition-all duration-200',
                  _index === currentImageIndex
                    ? 'border-coffee-500 ring-2 ring-coffee-200'
                    : 'border-transparent hover:border-coffee-300'
                )}
                aria-label={`View image ${_index + 1}: ${image.alt}`}
              >
                {image.cloudinaryId ? (
                  <EnhancedProductImage
                    publicId={image.cloudinaryId}
                    alt={image.alt}
                    size="thumbnail"
                    className="h-full w-full object-cover"
                  />
                ) : (
                  <div className="flex h-full w-full items-center justify-center bg-gradient-to-br from-coffee-50 to-coffee-100">
                    <Coffee className="h-6 w-6 text-coffee-400" />
                  </div>
                )}

                {/* Primary Image Indicator */}
                {image.isPrimary && (
                  <div className="absolute right-1 top-1">
                    <div className="h-2 w-2 rounded-full bg-gold-500" />
                  </div>
                )}

                {/* Category Indicator */}
                {image.category && (
                  <div className="absolute bottom-0 left-0 right-0">
                    <div
                      className={cn('h-1', imageCategoryColors[image.category])}
                    />
                  </div>
                )}
              </button>
            ))}
          </div>
        )}
      </CardContent>
    </Card>
  );
}

import { type Locale } from '@/i18n';

// Base schema interfaces
interface BaseSchema {
  '@context': string;
  '@type': string;
}

interface ImageObject {
  '@type': 'ImageObject';
  url: string;
  width?: number;
  height?: number;
  alt?: string;
}

interface PostalAddress {
  '@type': 'PostalAddress';
  streetAddress: string;
  addressLocality: string;
  addressRegion?: string;
  postalCode?: string;
  addressCountry: string;
}

interface ContactPoint {
  '@type': 'ContactPoint';
  telephone: string;
  contactType: 'sales' | 'customer service' | 'technical support' | 'billing';
  availableLanguage: string[];
  email?: string;
}

interface Organization extends BaseSchema {
  '@type': 'Organization';
  name: string;
  alternateName?: string;
  url: string;
  logo: string | ImageObject;
  description: string;
  foundingDate?: string;
  address?: PostalAddress;
  contactPoint?: ContactPoint | ContactPoint[];
  sameAs?: string[];
  hasOfferCatalog?: OfferCatalog;
  aggregateRating?: AggregateRating;
  review?: Review[];
}

interface Product extends BaseSchema {
  '@type': 'Product';
  name: string;
  description: string;
  brand: Brand;
  category: string;
  image: string | ImageObject | ImageObject[];
  offers: Offer | Offer[];
  aggregateRating?: AggregateRating;
  review?: Review[];
  sku?: string;
  gtin?: string;
  mpn?: string;
  additionalProperty?: PropertyValue[];
}

interface Service extends BaseSchema {
  '@type': 'Service';
  name: string;
  description: string;
  provider: Organization;
  serviceType: string;
  areaServed: string | string[];
  hasOfferCatalog?: OfferCatalog;
  aggregateRating?: AggregateRating;
  review?: Review[];
  additionalProperty?: PropertyValue[];
}

interface Article extends BaseSchema {
  '@type': 'Article';
  headline: string;
  description: string;
  image: string | ImageObject;
  author: Person | Organization;
  publisher: Organization;
  datePublished: string;
  dateModified?: string;
  mainEntityOfPage: WebPage;
  articleSection?: string;
  keywords?: string[];
}

interface Offer {
  '@type': 'Offer';
  price?: string;
  priceCurrency?: string;
  availability: string;
  seller: Organization;
  validFrom?: string;
  validThrough?: string;
  priceSpecification?: PriceSpecification;
  itemCondition?: string;
  warranty?: WarrantyPromise;
}

interface OfferCatalog {
  '@type': 'OfferCatalog';
  name: string;
  itemListElement: Offer[];
}

interface Brand {
  '@type': 'Brand';
  name: string;
  logo?: string | ImageObject;
}

interface AggregateRating {
  '@type': 'AggregateRating';
  ratingValue: string;
  reviewCount: string;
  bestRating?: string;
  worstRating?: string;
}

interface Review {
  '@type': 'Review';
  reviewRating: Rating;
  author: Person;
  reviewBody: string;
  datePublished: string;
}

interface Rating {
  '@type': 'Rating';
  ratingValue: string;
  bestRating?: string;
  worstRating?: string;
}

interface Person {
  '@type': 'Person';
  name: string;
  jobTitle?: string;
  worksFor?: Organization;
}

interface WebPage {
  '@type': 'WebPage';
  '@id': string;
}

interface PropertyValue {
  '@type': 'PropertyValue';
  name: string;
  value: string;
}

interface PriceSpecification {
  '@type': 'PriceSpecification';
  price: string;
  priceCurrency: string;
  minPrice?: string;
  maxPrice?: string;
  unitCode?: string;
}

interface WarrantyPromise {
  '@type': 'WarrantyPromise';
  durationOfWarranty: string;
  warrantyScope: string;
}

