export const RiskAssessmentTool: React.FC<RiskAssessmentToolProps> = ({
  initialFactors = defaultRiskFactors,
  scenarios = defaultScenarios,
  onExport,
}) => {
  const [riskFactors, setRiskFactors] = useState<RiskFactor[]>(initialFactors);
  const [selectedScenario, setSelectedScenario] = useState<string | null>(null);
  const [activeTab, setActiveTab] = useState<
    'assessment' | 'scenarios' | 'mitigation'
  >('assessment');

  // Calculate risk scores
  const calculateRiskScore = useCallback(
    (factor: RiskFactor, scenarioAdjustments?: any) => {
      const probability =
        scenarioAdjustments?.adjustedProbability || factor.probability;
      const impact = scenarioAdjustments?.adjustedImpact || factor.impact;
      return (probability * impact * factor.weight) / 1000;
    },
    []
  );

  const overallRiskScore = useMemo(() => {
    const scenario = selectedScenario
      ? scenarios.find(s => s.id === selectedScenario)
      : null;

    return riskFactors.reduce((total, factor) => {
      const scenarioAdjustment = scenario?.factors.find(
        f => f.factorId === factor.id
      );
      return total + calculateRiskScore(factor, scenarioAdjustment);
    }, 0);
  }, [riskFactors, selectedScenario, scenarios, calculateRiskScore]);

  const getRiskLevel = (
    score: number
  ): { level: string; color: string; icon: React.ReactNode } => {
    if (score >= 70)
      return {
        level: 'Critical',
        color: 'text-red-600 bg-red-50 border-red-200',
        icon: <XCircle className="h-4 w-4 text-red-600" />,
      };
    if (score >= 50)
      return {
        level: 'High',
        color: 'text-orange-600 bg-orange-50 border-orange-200',
        icon: <AlertTriangle className="h-4 w-4 text-orange-600" />,
      };
    if (score >= 30)
      return {
        level: 'Medium',
        color: 'text-yellow-600 bg-yellow-50 border-yellow-200',
        icon: <Clock className="h-4 w-4 text-yellow-600" />,
      };
    return {
      level: 'Low',
      color: 'text-green-600 bg-green-50 border-green-200',
      icon: <CheckCircle className="h-4 w-4 text-green-600" />,
    };
  };

  // Prepare radar chart data
  const radarData = useMemo(() => {
    const scenario = selectedScenario
      ? scenarios.find(s => s.id === selectedScenario)
      : null;

    return riskFactors.map(factor => {
      const scenarioAdjustment = scenario?.factors.find(
        f => f.factorId === factor.id
      );
      const probability =
        scenarioAdjustment?.adjustedProbability || factor.probability;
      const impact = scenarioAdjustment?.adjustedImpact || factor.impact;

      return {
        factor: factor.name,
        score: calculateRiskScore(factor, scenarioAdjustment),
        probability,
        impact,
        weight: factor.weight * 10,
      };
    });
  }, [riskFactors, selectedScenario, scenarios, calculateRiskScore]);

  // Prepare bar chart data by category
  const categoryData = useMemo(() => {
    const categories = [
      'operational',
      'financial',
      'environmental',
      'political',
      'market',
    ];
    const scenario = selectedScenario
      ? scenarios.find(s => s.id === selectedScenario)
      : null;

    return categories.map(category => {
      const categoryFactors = riskFactors.filter(f => f.category === category);
      const totalScore = categoryFactors.reduce((sum, factor) => {
        const scenarioAdjustment = scenario?.factors.find(
          f => f.factorId === factor.id
        );
        return sum + calculateRiskScore(factor, scenarioAdjustment);
      }, 0);

      return {
        category: category.charAt(0).toUpperCase() + category.slice(1),
        score: totalScore,
        count: categoryFactors.length,
      };
    });
  }, [riskFactors, selectedScenario, scenarios, calculateRiskScore]);

  const updateFactorValue = (
    factorId: string,
    field: keyof RiskFactor,
    value: unknown
  ) => {
    setRiskFactors(prev =>
      prev.map(factor =>
        factor.id === factorId ? { ...factor, [field]: value } : factor
      )
    );
  };

  const exportAssessment = () => {
    const exportData = {
      timestamp: new Date().toISOString(),
      overallRiskScore,
      riskLevel: getRiskLevel(overallRiskScore).level,
      selectedScenario,
      factors: riskFactors,
      categoryBreakdown: categoryData,
      scenarios: scenarios,
    };

    if (onExport) {
      onExport(exportData);
    } else {
      downloadJSON(exportData, `risk-assessment-${Date.now()}`);
    }
  };

  const resetToDefaults = () => {
    setRiskFactors(defaultRiskFactors);
    setSelectedScenario(null);
  };

  const currentRiskLevel = getRiskLevel(overallRiskScore);

  return (
    <div className="w-full space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h3 className="text-xl font-semibold text-gray-900">
            Risk Assessment Tool
          </h3>
          <p className="text-sm text-gray-600">
            Evaluate and manage supply chain risks
          </p>
        </div>
        <div className="flex items-center space-x-2">
          <button
            onClick={resetToDefaults}
            className="flex items-center space-x-2 rounded-md border border-gray-300 px-3 py-2 text-sm hover:bg-gray-50"
          >
            <RefreshCw className="h-4 w-4" />
            <span>Reset</span>
          </button>
          <button
            onClick={exportAssessment}
            className="flex items-center space-x-2 rounded-md bg-blue-600 px-3 py-2 text-sm text-white hover:bg-blue-700"
          >
            <Download className="h-4 w-4" />
            <span>Export</span>
          </button>
        </div>
      </div>

      {/* Overall Risk Score */}
      <div className={`rounded-lg border p-4 ${currentRiskLevel.color}`}>
        <div className="flex items-center justify-between">
          <div className="flex items-center space-x-3">
            {currentRiskLevel.icon}
            <div>
              <h4 className="font-medium">
                Overall Risk Level: {currentRiskLevel.level}
              </h4>
              <p className="text-sm opacity-75">
                Risk Score: {overallRiskScore.toFixed(1)}/100
              </p>
            </div>
          </div>
          <div className="text-right">
            <div className="text-2xl font-bold">
              {overallRiskScore.toFixed(0)}
            </div>
            <div className="text-sm opacity-75">Risk Points</div>
          </div>
        </div>
      </div>

      {/* Scenario Selector */}
      <div className="space-y-2">
        <label className="block text-sm font-medium text-gray-700">
          Scenario Analysis
        </label>
        <select
          value={selectedScenario || ''}
          onChange={e => setSelectedScenario(e.target.value || null)}
          className="w-full rounded-md border border-gray-300 px-3 py-2 focus:outline-none focus:ring-2 focus:ring-blue-500"
        >
          <option value="">Baseline (Current Conditions)</option>
          {scenarios.map(scenario => (
            <option key={scenario.id} value={scenario.id}>
              {scenario.name} (Likelihood: {scenario.likelihood}%)
            </option>
          ))}
        </select>
        {selectedScenario && (
          <p className="text-sm text-gray-600">
            {scenarios.find(s => s.id === selectedScenario)?.description}
          </p>
        )}
      </div>

      {/* Tabs */}
      <div className="border-b border-gray-200">
        <nav
          className="-mb-px flex space-x-8"
          aria-label="Risk assessment tabs"
        >
          {[
            { key: 'assessment', label: 'Risk Assessment', icon: Calculator },
            { key: 'scenarios', label: 'Scenario Analysis', icon: TrendingUp },
            { key: 'mitigation', label: 'Mitigation Strategies', icon: Shield },
          ].map(({ key, label, icon: Icon }) => (
            <button
              key={key}
              onClick={() => setActiveTab(key as 'assessment' | 'scenarios' | 'mitigation')}
              className={`flex items-center space-x-2 border-b-2 px-1 py-2 text-sm font-medium ${
                activeTab === key
                  ? 'border-blue-500 text-blue-600'
                  : 'border-transparent text-gray-500 hover:border-gray-300 hover:text-gray-700'
              }`}
            >
              <Icon className="h-4 w-4" />
              <span>{label}</span>
            </button>
          ))}
        </nav>
      </div>

      {/* Tab Content */}
      {activeTab === 'assessment' && (
        <div className="grid grid-cols-1 gap-6 lg:grid-cols-2">
          {/* Radar Chart */}
          <div className="rounded-lg border border-gray-200 bg-white p-4">
            <h4 className="mb-4 font-medium text-gray-900">
              Risk Factor Analysis
            </h4>
            <ResponsiveContainer width="100%" height={300}>
              <RadarChart data={radarData}>
                <PolarGrid />
                <PolarAngleAxis dataKey="factor" tick={{ fontSize: 10 }} />
                <PolarRadiusAxis
                  angle={90}
                  domain={[0, 100]}
                  tick={{ fontSize: 10 }}
                />
                <Radar
                  name="Risk Score"
                  dataKey="score"
                  stroke="#ef4444"
                  fill="#ef4444"
                  fillOpacity={0.3}
                  strokeWidth={2}
                />
              </RadarChart>
            </ResponsiveContainer>
          </div>

          {/* Category Breakdown */}
          <div className="rounded-lg border border-gray-200 bg-white p-4">
            <h4 className="mb-4 font-medium text-gray-900">Risk by Category</h4>
            <ResponsiveContainer width="100%" height={300}>
              <BarChart data={categoryData}>
                <CartesianGrid strokeDasharray="3 3" />
                <XAxis dataKey="category" tick={{ fontSize: 10 }} />
                <YAxis tick={{ fontSize: 10 }} />
                <Tooltip />
                <Bar dataKey="score" fill="#3b82f6" />
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>
      )}

      {activeTab === 'scenarios' && (
        <div className="space-y-4">
          {scenarios.map(scenario => (
            <div
              key={scenario.id}
              className="rounded-lg border border-gray-200 bg-white p-4"
            >
              <div className="mb-2 flex items-center justify-between">
                <h4 className="font-medium text-gray-900">{scenario.name}</h4>
                <span className="text-sm text-gray-500">
                  Likelihood: {scenario.likelihood}%
                </span>
              </div>
              <p className="mb-3 text-sm text-gray-600">
                {scenario.description}
              </p>
              <div className="grid grid-cols-1 gap-3 md:grid-cols-3">
                {scenario.factors.map(factor => {
                  const originalFactor = riskFactors.find(
                    f => f.id === factor.factorId
                  );
                  if (!originalFactor) return null;

                  return (
                    <div
                      key={factor.factorId}
                      className="rounded bg-gray-50 p-3"
                    >
                      <div className="text-sm font-medium text-gray-900">
                        {originalFactor.name}
                      </div>
                      <div className="mt-1 text-xs text-gray-600">
                        Probability: {factor.adjustedProbability}% (
                        {factor.adjustedProbability > originalFactor.probability
                          ? '+'
                          : ''}
                        {factor.adjustedProbability -
                          originalFactor.probability}
                        )
                      </div>
                      <div className="text-xs text-gray-600">
                        Impact: {factor.adjustedImpact}% (
                        {factor.adjustedImpact > originalFactor.impact
                          ? '+'
                          : ''}
                        {factor.adjustedImpact - originalFactor.impact})
                      </div>
                    </div>
                  );
                })}
              </div>
            </div>
          ))}
        </div>
      )}

      {activeTab === 'mitigation' && (
        <div className="space-y-4">
          {riskFactors.map(factor => {
            const riskScore = calculateRiskScore(factor);
            const riskLevel = getRiskLevel(riskScore);

            return (
              <div
                key={factor.id}
                className="rounded-lg border border-gray-200 bg-white p-4"
              >
                <div className="mb-3 flex items-center justify-between">
                  <div className="flex items-center space-x-3">
                    {riskLevel.icon}
                    <h4 className="font-medium text-gray-900">{factor.name}</h4>
                  </div>
                  <span
                    className={`rounded-full px-2 py-1 text-xs font-medium ${riskLevel.color}`}
                  >
                    {riskLevel.level} Risk
                  </span>
                </div>

                <div className="mb-3">
                  <div className="mb-2 text-sm text-gray-600">
                    Mitigation Strategies:
                  </div>
                  <ul className="space-y-1">
                    {factor.mitigation.map((strategy, _index) => (
                      <li
                        key={_index}
                        className="flex items-start space-x-2 text-sm"
                      >
                        <CheckCircle className="mt-0.5 h-4 w-4 flex-shrink-0 text-green-500" />
                        <span>{strategy}</span>
                      </li>
                    ))}
                  </ul>
                </div>

                <div className="grid grid-cols-3 gap-4 text-sm">
                  <div>
                    <label className="mb-1 block text-gray-600">
                      Probability (%)
                    </label>
                    <input
                      type="range"
                      min="0"
                      max="100"
                      value={factor.probability}
                      onChange={e =>
                        updateFactorValue(
                          factor.id,
                          'probability',
                          parseInt(e.target.value)
                        )
                      }
                      className="w-full"
                    />
                    <span className="text-gray-500">{factor.probability}%</span>
                  </div>
                  <div>
                    <label className="mb-1 block text-gray-600">
                      Impact (%)
                    </label>
                    <input
                      type="range"
                      min="0"
                      max="100"
                      value={factor.impact}
                      onChange={e =>
                        updateFactorValue(
                          factor.id,
                          'impact',
                          parseInt(e.target.value)
                        )
                      }
                      className="w-full"
                    />
                    <span className="text-gray-500">{factor.impact}%</span>
                  </div>
                  <div>
                    <label className="mb-1 block text-gray-600">
                      Weight (1-10)
                    </label>
                    <input
                      type="range"
                      min="1"
                      max="10"
                      value={factor.weight}
                      onChange={e =>
                        updateFactorValue(
                          factor.id,
                          'weight',
                          parseInt(e.target.value)
                        )
                      }
                      className="w-full"
                    />
                    <span className="text-gray-500">{factor.weight}/10</span>
                  </div>
                </div>
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
};

'use client';

import {
  Calculator,
  TrendingDown,
  Package,
  DollarSign,
  Truck,
  Calendar,
  AlertCircle,
  CheckCircle,
  Download,
  Share2,
} from 'lucide-react';
import React, { useState, useEffect } from 'react';

import { type CatalogProduct } from '@/data/product-catalog';
import { Badge } from '@/presentation/components/ui/badge';
import { Button } from '@/presentation/components/ui/button';
import { Card, CardContent } from '@/presentation/components/ui/card';
import { Input } from '@/presentation/components/ui/input';
import { Label } from '@/presentation/components/ui/label';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/presentation/components/ui/select';
import { SectionHeading } from '@/shared/components/design-system/Typography/Heading';

interface BulkPricingCalculatorProps {
  product: CatalogProduct;
  className?: string;
}

interface PricingCalculation {
  quantity: number;
  unitPrice: number;
  totalPrice: number;
  discountPercent: number;
  discountAmount: number;
  estimatedShipping: number;
  totalWithShipping: number;
  leadTime: number;
  paymentTerms: string;
}

export function BulkPricingCalculator({
  product,
  className,
}: BulkPricingCalculatorProps) {
  const [quantity, setQuantity] = useState<number>(
    product.pricing.minimumOrder
  );
  const [selectedUnit, setSelectedUnit] = useState<string>('MT');
  const [selectedIncoterm, setSelectedIncoterm] = useState<string>('FOB');
  const [calculation, setCalculation] = useState<PricingCalculation | null>(
    null
  );
  const [showBreakdown, setShowBreakdown] = useState(false);

  // Convert quantity to base unit (MT) for calculations
  const getQuantityInMT = (qty: number, unit: string): number => {
    switch (unit) {
      case 'MT':
        return qty;
      case 'kg':
        return qty / 1000;
      case 'lbs':
        return qty / 2204.62;
      case 'containers':
        return qty * 18; // Assuming 18 MT per container
      default:
        return qty;
    }
  };

  // Calculate pricing based on quantity and discounts
  const calculatePricing = (qty: number, unit: string): PricingCalculation => {
    const quantityInMT = getQuantityInMT(qty, unit);

    // Find applicable discount tier
    let discountPercent = 0;
    if (product.pricing.discountTiers) {
      const applicableTier = product.pricing.discountTiers
        .filter(tier => quantityInMT >= tier.minQuantity)
        .sort((a, b) => b.discountPercent - a.discountPercent)[0];

      if (applicableTier) {
        discountPercent = applicableTier.discountPercent;
      }
    }

    const unitPrice = product.pricing.basePrice * (1 - discountPercent / 100);
    const totalPrice = unitPrice * quantityInMT;
    const discountAmount =
      (product.pricing.basePrice - unitPrice) * quantityInMT;

    // Estimate shipping costs based on Incoterms and quantity
    let estimatedShipping = 0;
    if (selectedIncoterm === 'CIF' || selectedIncoterm === 'CFR') {
      estimatedShipping = quantityInMT * 150; // $150 per MT for shipping
    } else if (selectedIncoterm === 'DDP') {
      estimatedShipping = quantityInMT * 250; // $250 per MT for full delivery
    }

    // Adjust lead time based on quantity
    let leadTime = product.availability.leadTime;
    if (quantityInMT > 100) {
      leadTime += 7; // Additional week for large orders
    }

    return {
      quantity: quantityInMT,
      unitPrice,
      totalPrice,
      discountPercent,
      discountAmount,
      estimatedShipping,
      totalWithShipping: totalPrice + estimatedShipping,
      leadTime,
      paymentTerms: product.pricing.paymentTerms,
    };
  };

  useEffect(() => {
    if (quantity > 0) {
      const calc = calculatePricing(quantity, selectedUnit);
      setCalculation(calc);
    }
  }, [quantity, selectedUnit, selectedIncoterm, product]);

  const handleQuantityChange = (value: string) => {
    const numValue = parseFloat(value);
    if (!isNaN(numValue) && numValue >= 0) {
      setQuantity(numValue);
    }
  };

  const isValidOrder =
    calculation && calculation.quantity >= product.pricing.minimumOrder;

  const exportQuote = () => {
    if (!calculation) return;

    const quoteData = {
      product: product.name,
      quantity: `${quantity} ${selectedUnit}`,
      unitPrice: `$${calculation.unitPrice.toFixed(2)}`,
      totalPrice: `$${calculation.totalPrice.toLocaleString()}`,
      discount: `${calculation.discountPercent}%`,
      incoterms: selectedIncoterm,
      leadTime: `${calculation.leadTime} days`,
      validUntil: product.pricing.priceValidUntil,
    };

    // In a real app, this would generate a PDF or send to CRM
    // Quote export tracking removed for production
    alert(
      'Quote exported! In production, this would generate a PDF or send to your CRM.'
    );
  };

  return (
    <Card className={`shadow-lg ${className}`}>
      <CardContent className="p-6">
        <SectionHeading size="lg" className="mb-6 text-coffee-800">
          <div className="flex items-center">
            <Calculator className="mr-3 h-6 w-6" />
            Bulk Pricing Calculator
          </div>
        </SectionHeading>

        {/* Input Controls */}
        <div className="mb-6 grid grid-cols-1 gap-4 md:grid-cols-3">
          <div>
            <Label
              htmlFor="quantity"
              className="text-sm font-medium text-coffee-700"
            >
              Quantity
            </Label>
            <Input
              id="quantity"
              type="number"
              value={quantity}
              onChange={e => handleQuantityChange(e.target.value)}
              min={0}
              step={selectedUnit === 'kg' ? 100 : 1}
              className="mt-1"
            />
          </div>

          <div>
            <Label
              htmlFor="unit"
              className="text-sm font-medium text-coffee-700"
            >
              Unit
            </Label>
            <Select value={selectedUnit} onValueChange={setSelectedUnit}>
              <SelectTrigger className="mt-1">
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="MT">Metric Tons (MT)</SelectItem>
                <SelectItem value="kg">Kilograms (kg)</SelectItem>
                <SelectItem value="lbs">Pounds (lbs)</SelectItem>
                <SelectItem value="containers">Containers (20ft)</SelectItem>
              </SelectContent>
            </Select>
          </div>

          <div>
            <Label
              htmlFor="incoterms"
              className="text-sm font-medium text-coffee-700"
            >
              Incoterms
            </Label>
            <Select
              value={selectedIncoterm}
              onValueChange={setSelectedIncoterm}
            >
              <SelectTrigger className="mt-1">
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="FOB">FOB (Free on Board)</SelectItem>
                <SelectItem value="CFR">CFR (Cost and Freight)</SelectItem>
                <SelectItem value="CIF">
                  CIF (Cost, Insurance, Freight)
                </SelectItem>
                <SelectItem value="DDP">DDP (Delivered Duty Paid)</SelectItem>
              </SelectContent>
            </Select>
          </div>
        </div>

        {/* Validation Alert */}
        {calculation && !isValidOrder && (
          <div className="mb-4 rounded-lg border border-red-200 bg-red-50 p-4">
            <div className="flex items-center">
              <AlertCircle className="mr-3 h-5 w-5 text-red-600" />
              <div>
                <h4 className="text-sm font-semibold text-red-800">
                  Minimum Order Required
                </h4>
                <p className="text-xs text-red-700">
                  Minimum order quantity is {product.pricing.minimumOrder} MT.
                  Current quantity: {calculation.quantity.toFixed(2)} MT
                </p>
              </div>
            </div>
          </div>
        )}

        {/* Pricing Results */}
        {calculation && isValidOrder && (
          <div className="space-y-4">
            {/* Main Pricing Display */}
            <div className="rounded-lg border border-green-200 bg-gradient-to-r from-green-50 to-emerald-50 p-6">
              <div className="grid grid-cols-1 gap-4 md:grid-cols-2">
                <div>
                  <div className="mb-2 flex items-center justify-between">
                    <span className="text-sm font-medium text-green-700">
                      Unit Price
                    </span>
                    {calculation.discountPercent > 0 && (
                      <Badge
                        variant="secondary"
                        className="bg-green-100 text-green-800"
                      >
                        <TrendingDown className="mr-1 h-3 w-3" />
                        {calculation.discountPercent}% OFF
                      </Badge>
                    )}
                  </div>
                  <p className="text-2xl font-bold text-green-800">
                    ${calculation.unitPrice.toFixed(2)}/MT
                  </p>
                  {calculation.discountPercent > 0 && (
                    <p className="text-sm text-green-600 line-through">
                      ${product.pricing.basePrice.toFixed(2)}/MT
                    </p>
                  )}
                </div>

                <div>
                  <span className="text-sm font-medium text-green-700">
                    Total Price
                  </span>
                  <p className="text-2xl font-bold text-green-800">
                    ${calculation.totalPrice.toLocaleString()}
                  </p>
                  {calculation.discountAmount > 0 && (
                    <p className="text-sm text-green-600">
                      You save: ${calculation.discountAmount.toLocaleString()}
                    </p>
                  )}
                </div>
              </div>
            </div>

            {/* Detailed Breakdown */}
            <div className="grid grid-cols-1 gap-4 md:grid-cols-2 lg:grid-cols-4">
              <div className="rounded-lg border border-blue-200 bg-blue-50 p-4">
                <div className="mb-2 flex items-center justify-between">
                  <Package className="h-5 w-5 text-blue-600" />
                  <span className="text-xs font-medium text-blue-700">
                    QUANTITY
                  </span>
                </div>
                <p className="text-lg font-bold text-blue-800">
                  {calculation.quantity.toFixed(2)} MT
                </p>
                <p className="text-xs text-blue-600">
                  {quantity} {selectedUnit}
                </p>
              </div>

              <div className="rounded-lg border border-purple-200 bg-purple-50 p-4">
                <div className="mb-2 flex items-center justify-between">
                  <Calendar className="h-5 w-5 text-purple-600" />
                  <span className="text-xs font-medium text-purple-700">
                    LEAD TIME
                  </span>
                </div>
                <p className="text-lg font-bold text-purple-800">
                  {calculation.leadTime} days
                </p>
                <p className="text-xs text-purple-600">
                  {calculation.paymentTerms}
                </p>
              </div>

              {calculation.estimatedShipping > 0 && (
                <div className="rounded-lg border border-orange-200 bg-orange-50 p-4">
                  <div className="mb-2 flex items-center justify-between">
                    <Truck className="h-5 w-5 text-orange-600" />
                    <span className="text-xs font-medium text-orange-700">
                      SHIPPING
                    </span>
                  </div>
                  <p className="text-lg font-bold text-orange-800">
                    ${calculation.estimatedShipping.toLocaleString()}
                  </p>
                  <p className="text-xs text-orange-600">
                    {selectedIncoterm} terms
                  </p>
                </div>
              )}

              <div className="rounded-lg border border-gold-200 bg-gold-50 p-4">
                <div className="mb-2 flex items-center justify-between">
                  <DollarSign className="h-5 w-5 text-gold-600" />
                  <span className="text-xs font-medium text-gold-700">
                    TOTAL
                  </span>
                </div>
                <p className="text-lg font-bold text-gold-800">
                  ${calculation.totalWithShipping.toLocaleString()}
                </p>
                <p className="text-xs text-gold-600">Including all costs</p>
              </div>
            </div>

            {/* Action Buttons */}
            <div className="flex flex-col gap-3 sm:flex-row">
              <Button
                onClick={exportQuote}
                className="flex-1 bg-coffee-600 hover:bg-coffee-700"
              >
                <Download className="mr-2 h-4 w-4" />
                Export Quote
              </Button>

              <Button
                variant="outline"
                onClick={() => setShowBreakdown(!showBreakdown)}
                className="flex-1"
              >
                <Calculator className="mr-2 h-4 w-4" />
                {showBreakdown ? 'Hide' : 'Show'} Breakdown
              </Button>

              <Button
                variant="outline"
                onClick={() => {
                  navigator.share?.({
                    title: `${product.name} - Bulk Quote`,
                    text: `Quote for ${quantity} ${selectedUnit} at $${calculation.unitPrice.toFixed(2)}/MT`,
                    url: window.location.href,
                  });
                }}
              >
                <Share2 className="mr-2 h-4 w-4" />
                Share
              </Button>
            </div>

            {/* Detailed Breakdown */}
            {showBreakdown && (
              <Card className="bg-gray-50">
                <CardContent className="p-4">
                  <h4 className="mb-3 text-sm font-semibold text-coffee-800">
                    Price Breakdown
                  </h4>
                  <div className="space-y-2 text-sm">
                    <div className="flex justify-between">
                      <span className="text-gray-600">
                        Base Price ({calculation.quantity.toFixed(2)} MT × $
                        {product.pricing.basePrice})
                      </span>
                      <span className="text-gray-800">
