  TooltipContent,
  TooltipProvider,
  TooltipTrigger,
} from '@/presentation/components/ui/tooltip';

interface ContentMetadata {
  title: string;
  description: string;
  excerpt: string;
  seoTitle: string;
  seoDescription: string;
  keywords: string[];
  locale: string;
  category: string;
  featured: boolean;
  publishedAt: string;
  author: string;
  coverImage: string;
  slug: string;
  status: 'draft' | 'published' | 'archived';
}

interface ContentEditorProps {
  initialContent?: string;
  initialMetadata?: Partial<ContentMetadata>;
  contentType: 'blog' | 'market-report' | 'origin-story' | 'service';
  onSave: (content: string, metadata: ContentMetadata) => Promise<void>;
  onPreview?: (content: string, metadata: ContentMetadata) => void;
  isLoading?: boolean;
}

const defaultMetadata: ContentMetadata = {
  title: '',
  description: '',
  excerpt: '',
  seoTitle: '',
  seoDescription: '',
  keywords: [],
  locale: 'en',
  category: '',
  featured: false,
  publishedAt: new Date().toISOString().split('T')[0] as string,
  author: 'Admin',
  coverImage: '',
  slug: '',
  status: 'draft',
};

const toolbarButtons = [
  { icon: Bold, action: 'bold', tooltip: 'Bold (Ctrl+B)' },
  { icon: Italic, action: 'italic', tooltip: 'Italic (Ctrl+I)' },
  { icon: Heading1, action: 'h1', tooltip: 'Heading 1' },
  { icon: Heading2, action: 'h2', tooltip: 'Heading 2' },
  { icon: Heading3, action: 'h3', tooltip: 'Heading 3' },
  { icon: List, action: 'ul', tooltip: 'Bullet List' },
  { icon: ListOrdered, action: 'ol', tooltip: 'Numbered List' },
  { icon: Quote, action: 'quote', tooltip: 'Quote' },
  { icon: Code, action: 'code', tooltip: 'Code Block' },
  { icon: Link, action: 'link', tooltip: 'Insert Link' },
  { icon: Image, action: 'image', tooltip: 'Insert Image' },
];

export function ContentEditor({
  initialContent = '',
  initialMetadata = {},
  contentType,
  onSave,
  onPreview,
  isLoading = false,
}: ContentEditorProps) {
  const [content, setContent] = useState(initialContent);
  const [metadata, setMetadata] = useState<ContentMetadata>({
    ...defaultMetadata,
    ...initialMetadata,
  });
  const [showPreview, setShowPreview] = useState(false);
  const [showSettings, setShowSettings] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const [hasUnsavedChanges, setHasUnsavedChanges] = useState(false);

  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const [history, setHistory] = useState<string[]>([initialContent]);
  const [historyIndex, setHistoryIndex] = useState(0);

  // Auto-generate slug from title
  useEffect(() => {
    if (metadata.title && !metadata.slug) {
      const slug = metadata.title
        .toLowerCase()
        .replace(/[^a-z0-9\s-]/g, '')
        .replace(/\s+/g, '-')
        .replace(/-+/g, '-')
        .trim();
      setMetadata(prev => ({ ...prev, slug }));
    }
  }, [metadata.title]);

  // Track unsaved changes
  useEffect(() => {
    setHasUnsavedChanges(
      content !== initialContent ||
        JSON.stringify(metadata) !==
          JSON.stringify({ ...defaultMetadata, ...initialMetadata })
    );
  }, [content, metadata, initialContent, initialMetadata]);

  const insertText = useCallback(
    (before: string, after: string = '') => {
      const textarea = textareaRef.current;
      if (!textarea) return;

      const start = textarea.selectionStart;
      const end = textarea.selectionEnd;
      const selectedText = content.substring(start, end);
      const newText =
        content.substring(0, start) +
        before +
        selectedText +
        after +
        content.substring(end);

      setContent(newText);

      // Update history
      const newHistory = history.slice(0, historyIndex + 1);
      newHistory.push(newText);
      setHistory(newHistory);
      setHistoryIndex(newHistory.length - 1);

      // Focus and set cursor position
      setTimeout(() => {
        textarea.focus();
        const newCursorPos = start + before.length + selectedText.length;
        textarea.setSelectionRange(newCursorPos, newCursorPos);
      }, 0);
    },
    [content, history, historyIndex]
  );

  const handleToolbarAction = useCallback(
    (action: string) => {
      switch (action) {
        case 'bold':
          insertText('**', '**');
          break;
        case 'italic':
          insertText('*', '*');
          break;
        case 'h1':
          insertText('# ');
          break;
        case 'h2':
          insertText('## ');
          break;
        case 'h3':
          insertText('### ');
          break;
        case 'ul':
          insertText('- ');
          break;
        case 'ol':
          insertText('1. ');
          break;
        case 'quote':
          insertText('> ');
          break;
        case 'code':
          insertText('```\n', '\n```');
          break;
        case 'link':
          insertText('[', '](url)');
          break;
        case 'image':
          insertText('![alt text](', ')');
          break;
      }
    },
    [insertText]
  );

  const handleUndo = useCallback(() => {
    if (historyIndex > 0) {
      setHistoryIndex(historyIndex - 1);
      const previousContent = history[historyIndex - 1];
      if (previousContent !== undefined) {
        setContent(previousContent);
      }
    }
  }, [history, historyIndex]);

  const handleRedo = useCallback(() => {
    if (historyIndex < history.length - 1) {
      setHistoryIndex(historyIndex + 1);
      const nextContent = history[historyIndex + 1];
      if (nextContent !== undefined) {
        setContent(nextContent);
      }
    }
  }, [history, historyIndex]);

  const handleSave = async () => {
    setIsSaving(true);
    try {
      await onSave(content, metadata);
      setHasUnsavedChanges(false);
    } catch (_error) {
      // Error handling - could be logged to external service in production
    } finally {
      setIsSaving(false);
    }
  };

  const handlePreview = () => {
    if (onPreview) {
      onPreview(content, metadata);
    }
    setShowPreview(!showPreview);
  };

  const updateMetadata = (
    key: keyof ContentMetadata,
    value: ContentMetadata[keyof ContentMetadata]
  ) => {
    setMetadata(prev => ({ ...prev, [key]: value }));
  };

  const addKeyword = (keyword: string) => {
    if (keyword && !metadata.keywords.includes(keyword)) {
      updateMetadata('keywords', [...metadata.keywords, keyword]);
    }
  };

  const removeKeyword = (keyword: string) => {
    updateMetadata(
      'keywords',
      metadata.keywords.filter(k => k !== keyword)
    );
  };

  return (
    <div className="flex h-full flex-col">
      {/* Header */}
      <div className="flex items-center justify-between border-b p-4">
        <div className="flex items-center gap-2">
          <FileText className="h-5 w-5" />
          <h2 className="text-lg font-semibold">
            {metadata.title || 'Untitled Content'}
          </h2>
          {hasUnsavedChanges && (
            <div className="flex items-center gap-1 text-sm text-yellow-600">
              <AlertCircle className="h-3 w-3" />
              Unsaved changes
            </div>
          )}
        </div>
        <div className="flex items-center gap-2">
          <TooltipProvider>
            <Tooltip>
              <TooltipTrigger asChild>
                <Button
                  variant="outline"
                  size="sm"
                  onClick={handleUndo}
                  disabled={historyIndex === 0}
                >
                  <Undo className="h-4 w-4" />
                </Button>
              </TooltipTrigger>
              <TooltipContent>Undo</TooltipContent>
            </Tooltip>
          </TooltipProvider>

          <TooltipProvider>
            <Tooltip>
              <TooltipTrigger asChild>
                <Button
                  variant="outline"
                  size="sm"
                  onClick={handleRedo}
                  disabled={historyIndex === history.length - 1}
                >
                  <Redo className="h-4 w-4" />
                </Button>
              </TooltipTrigger>
              <TooltipContent>Redo</TooltipContent>
            </Tooltip>
          </TooltipProvider>

          <Dialog open={showSettings} onOpenChange={setShowSettings}>
            <DialogTrigger asChild>
              <Button variant="outline" size="sm">
                <Settings className="mr-2 h-4 w-4" />
                Settings
              </Button>
            </DialogTrigger>
            <DialogContent className="max-w-2xl">
              <DialogHeader>
                <DialogTitle>Content Settings</DialogTitle>
                <DialogDescription>
                  Configure metadata and SEO settings for your content
                </DialogDescription>
              </DialogHeader>

              <Tabs defaultValue="general" className="w-full">
                <TabsList className="grid w-full grid-cols-3">
                  <TabsTrigger value="general">General</TabsTrigger>
                  <TabsTrigger value="seo">SEO</TabsTrigger>
                  <TabsTrigger value="publishing">Publishing</TabsTrigger>
                </TabsList>

                <TabsContent value="general" className="space-y-4">
                  <div className="grid gap-4">
                    <div>
                      <Label htmlFor="title">Title</Label>
                      <Input
                        id="title"
                        value={metadata.title}
                        onChange={e => updateMetadata('title', e.target.value)}
                        placeholder="Enter content title"
                      />
                    </div>
                    <div>
                      <Label htmlFor="description">Description</Label>
                      <Textarea
                        id="description"
                        value={metadata.description}
                        onChange={e =>
                          updateMetadata('description', e.target.value)
                        }
                        placeholder="Brief description of the content"
                        rows={3}
                      />
                    </div>
                    <div>
                      <Label htmlFor="excerpt">Excerpt</Label>
                      <Textarea
                        id="excerpt"
                        value={metadata.excerpt}
                        onChange={e =>
                          updateMetadata('excerpt', e.target.value)
                        }
                        placeholder="Short excerpt for previews"
                        rows={2}
                      />
                    </div>
                    <div>
                      <Label htmlFor="coverImage">Cover Image URL</Label>
                      <Input
                        id="coverImage"
                        value={metadata.coverImage}
                        onChange={e =>
                          updateMetadata('coverImage', e.target.value)
                        }
                        placeholder="https://example.com/image.jpg"
                      />
                    </div>
                  </div>
                </TabsContent>

                <TabsContent value="seo" className="space-y-4">
                  <div className="grid gap-4">
                    <div>
                      <Label htmlFor="seoTitle">SEO Title</Label>
                      <Input
                        id="seoTitle"
                        value={metadata.seoTitle}
                        onChange={e =>
                          updateMetadata('seoTitle', e.target.value)
                        }
                        placeholder="SEO optimized title"
                      />
                    </div>
                    <div>
                      <Label htmlFor="seoDescription">SEO Description</Label>
                      <Textarea
                        id="seoDescription"
                        value={metadata.seoDescription}
                        onChange={e =>
                          updateMetadata('seoDescription', e.target.value)
                        }
                        placeholder="SEO meta description"
                        rows={3}
                      />
                    </div>
                    <div>
                      <Label htmlFor="slug">URL Slug</Label>
                      <Input
                        id="slug"
                        value={metadata.slug}
                        onChange={e => updateMetadata('slug', e.target.value)}
                        placeholder="url-friendly-slug"
                      />
                    </div>
                    <div>
                      <Label>Keywords</Label>
                      <div className="mb-2 flex flex-wrap gap-2">
                        {metadata.keywords.map(keyword => (
                          <span
                            key={keyword}
                            className="inline-flex items-center gap-1 rounded-md bg-blue-100 px-2 py-1 text-sm text-blue-800"
                          >
                            {keyword}
                            <button
                              onClick={() => removeKeyword(keyword)}
                              className="text-blue-600 hover:text-blue-800"
                            >
                              ×
                            </button>
                          </span>
                        ))}
                      </div>
                      <Input
                        placeholder="Add keyword and press Enter"
                        onKeyDown={e => {
                          if (e.key === 'Enter') {
                            e.preventDefault();
                            addKeyword(e.currentTarget.value);
                            e.currentTarget.value = '';
                          }
                        }}
                      />
                    </div>
                  </div>
                </TabsContent>

                <TabsContent value="publishing" className="space-y-4">
                  <div className="grid gap-4">
                    <div>
                      <Label htmlFor="locale">Language</Label>
                      <Select
                        value={metadata.locale}
                        onValueChange={value => updateMetadata('locale', value)}
                      >
                        <SelectTrigger>
                          <SelectValue />
                        </SelectTrigger>
                        <SelectContent>
                          <SelectItem value="en">English</SelectItem>
                          <SelectItem value="de">German</SelectItem>
                          <SelectItem value="ja">Japanese</SelectItem>
                          <SelectItem value="vi">Vietnamese</SelectItem>
                        </SelectContent>
                      </Select>
                    </div>
                    <div>
                      <Label htmlFor="category">Category</Label>
                      <Input
                        id="category"
                        value={metadata.category}
                        onChange={e =>
                          updateMetadata('category', e.target.value)
                        }
                        placeholder="Content category"
                      />
                    </div>
                    <div>
                      <Label htmlFor="author">Author</Label>
                      <Input
                        id="author"
                        value={metadata.author}
                        onChange={e => updateMetadata('author', e.target.value)}
                        placeholder="Content author"
                      />
                    </div>
                    <div>
                      <Label htmlFor="publishedAt">Publish Date</Label>
                      <Input
                        id="publishedAt"
                        type="date"
                        value={metadata.publishedAt}
                        onChange={e =>
                          updateMetadata('publishedAt', e.target.value)
                        }
                      />
                    </div>
                    <div className="flex items-center space-x-2">
                      <Switch
                        id="featured"
                        checked={metadata.featured}
                        onCheckedChange={checked =>
                          updateMetadata('featured', checked)
                        }
                      />
                      <Label htmlFor="featured">Featured Content</Label>
                    </div>
                    <div>
                      <Label htmlFor="status">Status</Label>
                      <Select
                        value={metadata.status}
                        onValueChange={value => updateMetadata('status', value)}
                      >
                        <SelectTrigger>
                          <SelectValue />
                        </SelectTrigger>
                        <SelectContent>
                          <SelectItem value="draft">Draft</SelectItem>
                          <SelectItem value="published">Published</SelectItem>
                          <SelectItem value="archived">Archived</SelectItem>
                        </SelectContent>
                      </Select>
                    </div>
                  </div>
                </TabsContent>
              </Tabs>

              <DialogFooter>
                <Button
                  variant="outline"
                  onClick={() => setShowSettings(false)}
                >
                  Cancel
                </Button>
                <Button onClick={() => setShowSettings(false)}>
                  Save Settings
                </Button>
              </DialogFooter>
            </DialogContent>
          </Dialog>

          <Button variant="outline" size="sm" onClick={handlePreview}>
            {showPreview ? (
              <EyeOff className="mr-2 h-4 w-4" />
            ) : (
              <Eye className="mr-2 h-4 w-4" />
            )}
            {showPreview ? 'Hide Preview' : 'Preview'}
          </Button>

          <Button
            size="sm"
            onClick={handleSave}
            disabled={isSaving || isLoading}
          >
            <Save className="mr-2 h-4 w-4" />
            {isSaving ? 'Saving...' : 'Save'}
          </Button>
        </div>
      </div>

      {/* Toolbar */}
      <div className="flex items-center gap-1 border-b p-2">
        <TooltipProvider>
          {toolbarButtons.map(({ icon: Icon, action, tooltip }) => (
            <Tooltip key={action}>
              <TooltipTrigger asChild>
                <Button
                  variant="ghost"
                  size="sm"
                  onClick={() => handleToolbarAction(action)}
                  className="h-8 w-8 p-0"
                >
                  <Icon className="h-4 w-4" />
                </Button>
              </TooltipTrigger>
              <TooltipContent>{tooltip}</TooltipContent>
            </Tooltip>
          ))}
        </TooltipProvider>
      </div>

      {/* Editor Content */}
      <div className="flex flex-1 overflow-hidden">
        {/* Editor */}
        <div className={`flex flex-col ${showPreview ? 'w-1/2' : 'w-full'}`}>
          <div className="border-b p-2">
            <span className="text-sm font-medium">Editor</span>
          </div>
          <Textarea
            ref={textareaRef}
            value={content}
            onChange={e => setContent(e.target.value)}
            placeholder="Start writing your content in Markdown..."
            className="flex-1 resize-none border-0 focus-visible:ring-0"
            style={{ minHeight: '500px' }}
          />
        </div>

        {/* Preview */}
        {showPreview && (
          <div className="w-1/2 border-l">
            <div className="border-b p-2">
              <span className="text-sm font-medium">Preview</span>
            </div>
            <div className="h-full overflow-auto p-4">
              <div className="prose prose-sm max-w-none">
                {/* This would be replaced with actual MDX rendering */}
                <div
                  dangerouslySetInnerHTML={{
                    __html: content.replace(/\n/g, '<br>'),
                  }}
                />
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

'use client';

import {
  MoreHorizontal,
  Edit,
  Eye,
  Trash2,
  Copy,
  Archive,
  Star,
  StarOff,
  Calendar,
  User,
  Globe,
  Search,
  Filter,
  Plus,
  BookOpen,
  TrendingUp,
  Coffee,
  Briefcase,
  SortAsc,
  SortDesc,
  ChevronLeft,
  ChevronRight,
} from 'lucide-react';
import { useState, useMemo } from 'react';

import { Badge } from '@/presentation/components/ui/badge';
import { Button } from '@/presentation/components/ui/button';
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from '@/presentation/components/ui/card';
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from '@/presentation/components/ui/dropdown-menu';
import { Input } from '@/presentation/components/ui/input';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/presentation/components/ui/select';
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/presentation/components/ui/table';
import {
  Tabs,
  TabsContent,
  TabsList,
  TabsTrigger,
} from '@/presentation/components/ui/tabs';
import {
  Tooltip,
  TooltipContent,
  TooltipProvider,
  TooltipTrigger,
} from '@/presentation/components/ui/tooltip';

export interface ContentItem {
  id: string;
  title: string;
  slug: string;
  type: 'blog' | 'market-report' | 'origin-story' | 'service';
  status: 'draft' | 'published' | 'archived';
  locale: string;
  author: string;
  category: string;
  featured: boolean;
  publishedAt: string;
  updatedAt: string;
  views?: number;
  excerpt: string;
  coverImage?: string;
}

interface ContentListProps {
  items: ContentItem[];
  onEdit?: (item: ContentItem) => void;
  onPreview?: (item: ContentItem) => void;
  onDelete?: (item: ContentItem) => void;
  onDuplicate?: (item: ContentItem) => void;
  onToggleFeatured?: (item: ContentItem) => void;
  onArchive?: (item: ContentItem) => void;
  onCreate?: (type: ContentItem['type']) => void;
  loading?: boolean;
}

const contentTypeIcons = {
  blog: BookOpen,
  'market-report': TrendingUp,
  'origin-story': Coffee,
  service: Briefcase,
};

const contentTypeLabels = {
  blog: 'Blog Post',
  'market-report': 'Market Report',
  'origin-story': 'Origin Story',
  service: 'Service',
};

type SortField = 'title' | 'publishedAt' | 'updatedAt' | 'views' | 'author';
type SortDirection = 'asc' | 'desc';

export function ContentList({
  items,
  onEdit,
  onPreview,
  onDelete,
  onDuplicate,
  onToggleFeatured,
  onArchive,
  onCreate,
  loading = false,
}: ContentListProps) {
  const [searchQuery, setSearchQuery] = useState('');
  const [selectedType, setSelectedType] = useState<string>('all');
  const [selectedStatus, setSelectedStatus] = useState<string>('all');
  const [selectedLocale, setSelectedLocale] = useState<string>('all');
  const [sortField, setSortField] = useState<SortField>('updatedAt');
  const [sortDirection, setSortDirection] = useState<SortDirection>('desc');
  const [currentPage, setCurrentPage] = useState(1);
  const [itemsPerPage] = useState(10);
  const [viewMode, setViewMode] = useState<'table' | 'grid'>('table');

  // Get unique values for filters
  const uniqueTypes = Array.from(new Set(items.map(item => item.type)));
  const uniqueLocales = Array.from(new Set(items.map(item => item.locale)));
  const uniqueCategories = Array.from(
    new Set(items.map(item => item.category))
  );

  // Filter and sort items
  const filteredAndSortedItems = useMemo(() => {
    let filtered = items.filter(item => {
      const matchesSearch =
        item.title.toLowerCase().includes(searchQuery.toLowerCase()) ||
        item.excerpt.toLowerCase().includes(searchQuery.toLowerCase()) ||
        item.author.toLowerCase().includes(searchQuery.toLowerCase());
      const matchesType = selectedType === 'all' || item.type === selectedType;
      const matchesStatus =
        selectedStatus === 'all' || item.status === selectedStatus;
      const matchesLocale =
        selectedLocale === 'all' || item.locale === selectedLocale;

      return matchesSearch && matchesType && matchesStatus && matchesLocale;
    });

    // Sort items
    filtered.sort((a, b) => {
      let aValue: string | number = a[sortField] as string | number;
      let bValue: string | number = b[sortField] as string | number;

      if (sortField === 'publishedAt' || sortField === 'updatedAt') {
        aValue = new Date(aValue as string).getTime();
        bValue = new Date(bValue as string).getTime();
      } else if (typeof aValue === 'string' && typeof bValue === 'string') {
        aValue = aValue.toLowerCase();
        bValue = bValue.toLowerCase();
      }

      if (sortDirection === 'asc') {
        return aValue > bValue ? 1 : -1;
      } else {
        return aValue < bValue ? 1 : -1;
      }
    });

    return filtered;
  }, [
    items,
    searchQuery,
    selectedType,
    selectedStatus,
    selectedLocale,
    sortField,
    sortDirection,
  ]);

  // Pagination
  const totalPages = Math.ceil(filteredAndSortedItems.length / itemsPerPage);
  const paginatedItems = filteredAndSortedItems.slice(
    (currentPage - 1) * itemsPerPage,
    currentPage * itemsPerPage
  );

  const handleSort = (field: SortField) => {
    if (sortField === field) {
      setSortDirection(sortDirection === 'asc' ? 'desc' : 'asc');
    } else {
      setSortField(field);
      setSortDirection('desc');
    }
  };

  const getSortIcon = (field: SortField) => {
    if (sortField !== field) return null;
    return sortDirection === 'asc' ? (
      <SortAsc className="h-3 w-3" />
    ) : (
      <SortDesc className="h-3 w-3" />
    );
  };

  const getStatusBadge = (status: ContentItem['status']) => {
    const variants = {
      published: 'bg-green-100 text-green-800',
      draft: 'bg-yellow-100 text-yellow-800',
      archived: 'bg-gray-100 text-gray-800',
    };
    return <Badge className={variants[status]}>{status}</Badge>;
  };

  const formatDate = (dateString: string) => {
    return new Date(dateString).toLocaleDateString('en-US', {
      year: 'numeric',
      month: 'short',
      day: 'numeric',
    });
  };

  if (loading) {
    return (
      <div className="flex h-64 items-center justify-center">
        <div className="text-center">
          <div className="h-8 w-8 animate-spin rounded-full border-4 border-primary border-t-transparent"></div>
          <p className="mt-2 text-sm text-muted-foreground">
            Loading content...
          </p>
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-2xl font-bold">Content Management</h2>
          <p className="text-muted-foreground">
            Manage your blog posts, market reports, origin stories, and service
            pages
          </p>
        </div>
        <DropdownMenu>
          <DropdownMenuTrigger asChild>
            <Button>
              <Plus className="mr-2 h-4 w-4" />
              Create Content
            </Button>
          </DropdownMenuTrigger>
          <DropdownMenuContent align="end">
            {Object.entries(contentTypeLabels).map(([type, label]) => {
              const IconComponent =
                contentTypeIcons[type as keyof typeof contentTypeIcons];
              return (
                <DropdownMenuItem
                  key={type}
                  onClick={() => onCreate?.(type as ContentItem['type'])}
                >
                  <IconComponent className="mr-2 h-4 w-4" />
                  {label}
                </DropdownMenuItem>
              );
            })}
          </DropdownMenuContent>
        </DropdownMenu>
      </div>

      {/* Filters and Search */}
      <Card>
        <CardHeader>
          <CardTitle className="text-lg">Filters</CardTitle>
        </CardHeader>
        <CardContent>
          <div className="grid grid-cols-1 gap-4 md:grid-cols-2 lg:grid-cols-5">
            <div className="space-y-2">
              <label className="text-sm font-medium">Search</label>
              <div className="relative">
                <Search className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground" />
                <Input
                  placeholder="Search content..."
                  value={searchQuery}
                  onChange={e => setSearchQuery(e.target.value)}
                  className="pl-9"
                />
              </div>
            </div>

            <div className="space-y-2">
              <label className="text-sm font-medium">Content Type</label>
              <Select value={selectedType} onValueChange={setSelectedType}>
                <SelectTrigger>
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="all">All Types</SelectItem>
                  {uniqueTypes.map(type => (
                    <SelectItem key={type} value={type}>
                      {contentTypeLabels[type]}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>

            <div className="space-y-2">
              <label className="text-sm font-medium">Status</label>
              <Select value={selectedStatus} onValueChange={setSelectedStatus}>
                <SelectTrigger>
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="all">All Status</SelectItem>
                  <SelectItem value="published">Published</SelectItem>
                  <SelectItem value="draft">Draft</SelectItem>
                  <SelectItem value="archived">Archived</SelectItem>
                </SelectContent>
              </Select>
            </div>

            <div className="space-y-2">
              <label className="text-sm font-medium">Language</label>
              <Select value={selectedLocale} onValueChange={setSelectedLocale}>
                <SelectTrigger>
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="all">All Languages</SelectItem>
                  {uniqueLocales.map(locale => (
                    <SelectItem key={locale} value={locale}>
                      {locale.toUpperCase()}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>

            <div className="space-y-2">
              <label className="text-sm font-medium">View</label>
              <Tabs
                value={viewMode}
                onValueChange={value => setViewMode(value as 'table' | 'grid')}
              >
                <TabsList className="grid w-full grid-cols-2">
                  <TabsTrigger value="table">Table</TabsTrigger>
                  <TabsTrigger value="grid">Grid</TabsTrigger>
                </TabsList>
              </Tabs>
            </div>
          </div>
        </CardContent>
      </Card>

      {/* Content List */}
      {viewMode === 'table' ? (
        <Card>
          <Table>
            <TableHeader>
              <TableRow>
                <TableHead className="w-12"></TableHead>
                <TableHead>
                  <Button
                    variant="ghost"
                    size="sm"
                    onClick={() => handleSort('title')}
                    className="h-auto p-0 font-semibold"
                  >
                    Title {getSortIcon('title')}
                  </Button>
                </TableHead>
                <TableHead>Type</TableHead>
                <TableHead>Status</TableHead>
                <TableHead>
                  <Button
                    variant="ghost"
                    size="sm"
                    onClick={() => handleSort('author')}
                    className="h-auto p-0 font-semibold"
                  >
                    Author {getSortIcon('author')}
                  </Button>
                </TableHead>
                <TableHead>
                  <Button
                    variant="ghost"
                    size="sm"
                    onClick={() => handleSort('publishedAt')}
                    className="h-auto p-0 font-semibold"
                  >
                    Published {getSortIcon('publishedAt')}
                  </Button>
                </TableHead>
                <TableHead>
                  <Button
                    variant="ghost"
                    size="sm"
                    onClick={() => handleSort('updatedAt')}
                    className="h-auto p-0 font-semibold"
                  >
                    Updated {getSortIcon('updatedAt')}
                  </Button>
                </TableHead>
                <TableHead className="w-12"></TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {paginatedItems.map(item => {
                const IconComponent = contentTypeIcons[item.type];
                return (
                  <TableRow key={item.id}>
                    <TableCell>
                      <TooltipProvider>
                        <Tooltip>
                          <TooltipTrigger asChild>
                            <Button
                              variant="ghost"
                              size="sm"
                              onClick={() => onToggleFeatured?.(item)}
                              className="h-8 w-8 p-0"
                            >
                              {item.featured ? (
                                <Star className="h-4 w-4 fill-yellow-400 text-yellow-400" />
                              ) : (
                                <StarOff className="h-4 w-4 text-muted-foreground" />
                              )}
                            </Button>
                          </TooltipTrigger>
                          <TooltipContent>
                            {item.featured
                              ? 'Remove from featured'
                              : 'Mark as featured'}
                          </TooltipContent>
                        </Tooltip>
                      </TooltipProvider>
                    </TableCell>
                    <TableCell>
                      <div className="flex items-center gap-3">
                        {item.coverImage && (
                          <div className="h-10 w-16 overflow-hidden rounded bg-muted">
                            <img
                              src={item.coverImage}
                              alt={`Cover image for ${item.title}`}
                              className="h-full w-full object-cover"
                            />
                          </div>
                        )}
                        <div>
                          <div className="font-medium">{item.title}</div>
                          <div className="text-sm text-muted-foreground">
                            /{item.locale}/{item.slug}
                          </div>
                        </div>
                      </div>
                    </TableCell>
                    <TableCell>
                      <div className="flex items-center gap-2">
                        <IconComponent className="h-4 w-4" />
                        <span className="text-sm">
                          {contentTypeLabels[item.type]}
                        </span>
                      </div>
                    </TableCell>
                    <TableCell>{getStatusBadge(item.status)}</TableCell>
                    <TableCell>
                      <div className="flex items-center gap-2">
                        <User className="h-3 w-3 text-muted-foreground" />
                        <span className="text-sm">{item.author}</span>
                      </div>
                    </TableCell>
                    <TableCell>
                      <div className="flex items-center gap-2">
                        <Calendar className="h-3 w-3 text-muted-foreground" />
                        <span className="text-sm">
                          {formatDate(item.publishedAt)}
                        </span>
                      </div>
                    </TableCell>
                    <TableCell>
                      <span className="text-sm text-muted-foreground">
                        {formatDate(item.updatedAt)}
                      </span>
                    </TableCell>
                    <TableCell>
                      <DropdownMenu>
                        <DropdownMenuTrigger asChild>
                          <Button
                            variant="ghost"
                            size="sm"
                            className="h-8 w-8 p-0"
                          >
                            <MoreHorizontal className="h-4 w-4" />
                          </Button>
                        </DropdownMenuTrigger>
                        <DropdownMenuContent align="end">
                          <DropdownMenuItem onClick={() => onPreview?.(item)}>
                            <Eye className="mr-2 h-4 w-4" />
                            Preview
                          </DropdownMenuItem>
                          <DropdownMenuItem onClick={() => onEdit?.(item)}>
                            <Edit className="mr-2 h-4 w-4" />
                            Edit
                          </DropdownMenuItem>
                          <DropdownMenuItem onClick={() => onDuplicate?.(item)}>
                            <Copy className="mr-2 h-4 w-4" />
                            Duplicate
                          </DropdownMenuItem>
                          <DropdownMenuSeparator />
                          <DropdownMenuItem onClick={() => onArchive?.(item)}>
                            <Archive className="mr-2 h-4 w-4" />
                            Archive
                          </DropdownMenuItem>
                          <DropdownMenuItem
                            onClick={() => onDelete?.(item)}
                            className="text-destructive"
                          >
                            <Trash2 className="mr-2 h-4 w-4" />
                            Delete
                          </DropdownMenuItem>
                        </DropdownMenuContent>
                      </DropdownMenu>
                    </TableCell>
                  </TableRow>
                );
              })}
            </TableBody>
          </Table>
        </Card>
      ) : (
        <div className="grid grid-cols-1 gap-6 md:grid-cols-2 lg:grid-cols-3">
          {paginatedItems.map(item => {
            const IconComponent = contentTypeIcons[item.type];
            return (
              <Card key={item.id} className="overflow-hidden">
                {item.coverImage && (
                  <div className="aspect-video w-full overflow-hidden bg-muted">
                    <img
                      src={item.coverImage}
                      alt={`Cover image for ${item.title}`}
                      className="h-full w-full object-cover"
                    />
                  </div>
                )}
                <CardHeader className="pb-3">
                  <div className="flex items-start justify-between">
                    <div className="flex items-center gap-2">
                      <IconComponent className="h-4 w-4" />
                      <Badge variant="outline" className="text-xs">
                        {contentTypeLabels[item.type]}
                      </Badge>
                      {item.featured && (
                        <Star className="h-3 w-3 fill-yellow-400 text-yellow-400" />
                      )}
                    </div>
                    <DropdownMenu>
                      <DropdownMenuTrigger asChild>
                        <Button
                          variant="ghost"
                          size="sm"
                          className="h-8 w-8 p-0"
                        >
                          <MoreHorizontal className="h-4 w-4" />
                        </Button>
                      </DropdownMenuTrigger>
                      <DropdownMenuContent align="end">
                        <DropdownMenuItem onClick={() => onPreview?.(item)}>
                          <Eye className="mr-2 h-4 w-4" />
                          Preview
                        </DropdownMenuItem>
                        <DropdownMenuItem onClick={() => onEdit?.(item)}>
                          <Edit className="mr-2 h-4 w-4" />
                          Edit
                        </DropdownMenuItem>
                        <DropdownMenuItem onClick={() => onDuplicate?.(item)}>
                          <Copy className="mr-2 h-4 w-4" />
                          Duplicate
                        </DropdownMenuItem>
                        <DropdownMenuSeparator />
                        <DropdownMenuItem onClick={() => onArchive?.(item)}>
                          <Archive className="mr-2 h-4 w-4" />
                          Archive
                        </DropdownMenuItem>
                        <DropdownMenuItem
                          onClick={() => onDelete?.(item)}
                          className="text-destructive"
                        >
                          <Trash2 className="mr-2 h-4 w-4" />
                          Delete
                        </DropdownMenuItem>
                      </DropdownMenuContent>
                    </DropdownMenu>
                  </div>
                  <CardTitle className="line-clamp-2 text-lg">
                    {item.title}
                  </CardTitle>
                  <CardDescription className="line-clamp-2">
                    {item.excerpt}
                  </CardDescription>
                </CardHeader>
                <CardContent>
                  <div className="flex items-center justify-between text-sm text-muted-foreground">
                    <div className="flex items-center gap-4">
                      <div className="flex items-center gap-1">
                        <User className="h-3 w-3" />
                        {item.author}
                      </div>
                      <div className="flex items-center gap-1">
                        <Globe className="h-3 w-3" />
                        {item.locale.toUpperCase()}
                      </div>
                    </div>
                    {getStatusBadge(item.status)}
                  </div>
                  <div className="mt-2 text-xs text-muted-foreground">
                    Updated {formatDate(item.updatedAt)}
                  </div>
                </CardContent>
              </Card>
            );
          })}
        </div>
      )}

      {/* Pagination */}
      {totalPages > 1 && (
        <div className="flex items-center justify-between">
          <div className="text-sm text-muted-foreground">
            Showing {(currentPage - 1) * itemsPerPage + 1} to{' '}
            {Math.min(
              currentPage * itemsPerPage,
              filteredAndSortedItems.length
            )}{' '}
            of {filteredAndSortedItems.length} results
          </div>
          <div className="flex items-center gap-2">
            <Button
              variant="outline"
              size="sm"
              onClick={() => setCurrentPage(currentPage - 1)}
              disabled={currentPage === 1}
            >
              <ChevronLeft className="h-4 w-4" />
              Previous
            </Button>
            <div className="flex items-center gap-1">
              {Array.from({ length: totalPages }, (_, i) => i + 1)
                .filter(
                  page =>
                    page === 1 ||
                    page === totalPages ||
                    (page >= currentPage - 1 && page <= currentPage + 1)
                )
                .map((page, index, array) => (
                  <div key={page} className="flex items-center">
                    {index > 0 && array[index - 1] !== page - 1 && (
                      <span className="px-2 text-muted-foreground">...</span>
                    )}
                    <Button
                      variant={currentPage === page ? 'default' : 'outline'}
                      size="sm"
                      onClick={() => setCurrentPage(page)}
                      className="h-8 w-8 p-0"
                    >
                      {page}
                    </Button>
                  </div>
                ))}
            </div>
            <Button
              variant="outline"
              size="sm"
              onClick={() => setCurrentPage(currentPage + 1)}
              disabled={currentPage === totalPages}
            >
              Next
              <ChevronRight className="h-4 w-4" />
            </Button>
          </div>
        </div>
      )}

      {/* Empty State */}
      {filteredAndSortedItems.length === 0 && (
        <Card>
          <CardContent className="flex h-64 items-center justify-center">
            <div className="text-center">
              <BookOpen className="mx-auto h-12 w-12 text-muted-foreground" />
              <h3 className="mt-4 text-lg font-semibold">No content found</h3>
              <p className="mt-2 text-sm text-muted-foreground">
                {searchQuery ||
                selectedType !== 'all' ||
                selectedStatus !== 'all' ||
                selectedLocale !== 'all'
                  ? 'Try adjusting your filters or search query.'
                  : 'Get started by creating your first piece of content.'}
              </p>
              {!searchQuery &&
                selectedType === 'all' &&
                selectedStatus === 'all' &&
                selectedLocale === 'all' && (
                  <Button className="mt-4" onClick={() => onCreate?.('blog')}>
                    <Plus className="mr-2 h-4 w-4" />
                    Create Content
                  </Button>
                )}
            </div>
          </CardContent>
        </Card>
      )}
    </div>
  );
}

'use client';

import {
  Eye,
  ExternalLink,
  Smartphone,
  Tablet,
  Monitor,
  Globe,
  Calendar,
  User,
  Tag,
  Clock,
  Share2,
  BookOpen,
  TrendingUp,
  Coffee,
  Briefcase,
} from 'lucide-react';
import { useState } from 'react';

import { Badge } from '@/presentation/components/ui/badge';
import { Button } from '@/presentation/components/ui/button';
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from '@/presentation/components/ui/card';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/presentation/components/ui/select';
import {
  Tabs,
  TabsContent,
  TabsList,
  TabsTrigger,
} from '@/presentation/components/ui/tabs';
import {
  Tooltip,
  TooltipContent,
  TooltipProvider,
  TooltipTrigger,
} from '@/presentation/components/ui/tooltip';

interface ContentMetadata {
  title: string;
  description: string;
  excerpt: string;
  seoTitle: string;
  seoDescription: string;
  keywords: string[];
  locale: string;
  category: string;
  featured: boolean;
  publishedAt: string;
  author: string;
  coverImage: string;
  slug: string;
  status: 'draft' | 'published' | 'archived';
}

interface ContentPreviewProps {
  content: string;
  metadata: ContentMetadata;
  contentType: 'blog' | 'market-report' | 'origin-story' | 'service';
  onPublish?: () => void;
  onEdit?: () => void;
}

const contentTypeIcons = {
  blog: BookOpen,
  'market-report': TrendingUp,
  'origin-story': Coffee,
  service: Briefcase,
};

const deviceSizes = {
  mobile: { width: '375px', height: '667px', name: 'Mobile' },
  tablet: { width: '768px', height: '1024px', name: 'Tablet' },
  desktop: { width: '100%', height: '100%', name: 'Desktop' },
};

export function ContentPreview({
  content,
  metadata,
  contentType,
  onPublish,
  onEdit,
}: ContentPreviewProps) {
  const [selectedDevice, setSelectedDevice] =
    useState<keyof typeof deviceSizes>('desktop');
  const [showSEOPreview, setShowSEOPreview] = useState(false);

  const IconComponent = contentTypeIcons[contentType];
  const deviceConfig = deviceSizes[selectedDevice];

  // Simulate reading time calculation
  const readingTime = Math.ceil(content.split(' ').length / 200);

  // Generate preview URL
  const previewUrl = `/${metadata.locale}/${contentType === 'blog' ? 'blog' : contentType === 'market-report' ? 'market-reports' : contentType === 'origin-story' ? 'origin-stories' : 'services'}/${metadata.slug}`;

  return (
    <div className="flex h-full flex-col">
      {/* Header */}
      <div className="flex items-center justify-between border-b p-4">
        <div className="flex items-center gap-3">
          <IconComponent className="h-5 w-5" />
          <div>
            <h2 className="text-lg font-semibold">{metadata.title}</h2>
            <p className="text-sm text-muted-foreground">
              Preview • {contentType.replace('-', ' ')} •{' '}
              {metadata.locale.toUpperCase()}
            </p>
          </div>
        </div>
        <div className="flex items-center gap-2">
          {/* Device Selector */}
          <div className="flex items-center gap-1 rounded-md border p-1">
            <TooltipProvider>
              <Tooltip>
                <TooltipTrigger asChild>
                  <Button
                    variant={selectedDevice === 'mobile' ? 'default' : 'ghost'}
                    size="sm"
                    onClick={() => setSelectedDevice('mobile')}
                    className="h-8 w-8 p-0"
                  >
                    <Smartphone className="h-4 w-4" />
                  </Button>
                </TooltipTrigger>
                <TooltipContent>Mobile View</TooltipContent>
              </Tooltip>
            </TooltipProvider>

            <TooltipProvider>
              <Tooltip>
                <TooltipTrigger asChild>
                  <Button
                    variant={selectedDevice === 'tablet' ? 'default' : 'ghost'}
                    size="sm"
                    onClick={() => setSelectedDevice('tablet')}
                    className="h-8 w-8 p-0"
                  >
                    <Tablet className="h-4 w-4" />
                  </Button>
                </TooltipTrigger>
                <TooltipContent>Tablet View</TooltipContent>
              </Tooltip>
            </TooltipProvider>

            <TooltipProvider>
              <Tooltip>
                <TooltipTrigger asChild>
                  <Button
                    variant={selectedDevice === 'desktop' ? 'default' : 'ghost'}
                    size="sm"
                    onClick={() => setSelectedDevice('desktop')}
                    className="h-8 w-8 p-0"
                  >
                    <Monitor className="h-4 w-4" />
                  </Button>
                </TooltipTrigger>
                <TooltipContent>Desktop View</TooltipContent>
              </Tooltip>
            </TooltipProvider>
          </div>

          <Button
            variant="outline"
            size="sm"
            onClick={() => setShowSEOPreview(!showSEOPreview)}
          >
            <Eye className="mr-2 h-4 w-4" />
            SEO Preview
          </Button>

          <Button variant="outline" size="sm" onClick={onEdit}>
            Edit
          </Button>

          {metadata.status === 'draft' && onPublish && (
            <Button size="sm" onClick={onPublish}>
              <Share2 className="mr-2 h-4 w-4" />
              Publish
            </Button>
          )}
        </div>
      </div>

      <div className="flex flex-1 overflow-hidden">
        {/* Main Preview */}
        <div className="flex-1 overflow-auto">
          {showSEOPreview && (
            <div className="border-b bg-gray-50 p-4">
              <h3 className="mb-3 font-semibold">SEO Preview</h3>

              {/* Google Search Result Preview */}
              <div className="mb-4 rounded-md border bg-white p-4">
                <h4 className="mb-2 text-sm font-medium text-gray-600">
                  Google Search Result
                </h4>
                <div className="space-y-1">
                  <div className="text-sm text-green-700">{`greatbeans.com${previewUrl}`}</div>
                  <div className="cursor-pointer text-lg text-blue-600 hover:underline">
                    {metadata.seoTitle || metadata.title}
                  </div>
                  <div className="text-sm text-gray-600">
                    {metadata.seoDescription || metadata.description}
                  </div>
                </div>
              </div>

              {/* Social Media Preview */}
              <div className="rounded-md border bg-white p-4">
                <h4 className="mb-2 text-sm font-medium text-gray-600">
                  Social Media Preview
                </h4>
                <div className="flex gap-3">
                  {metadata.coverImage && (
                    <div className="flex h-20 w-32 items-center justify-center rounded bg-gray-200">
                      <img
                        src={metadata.coverImage}
                        alt="Cover"
                        className="h-full w-full rounded object-cover"
                        onError={e => {
                          e.currentTarget.style.display = 'none';
                          (e.currentTarget
                            .nextElementSibling as HTMLElement)!.style.display =
                            'flex';
                        }}
                      />
                      <div className="hidden h-full w-full items-center justify-center text-xs text-gray-500">
                        Image
                      </div>
                    </div>
                  )}
                  <div className="flex-1">
                    <div className="text-sm font-medium">{metadata.title}</div>
                    <div className="line-clamp-2 text-xs text-gray-600">
                      {metadata.description}
                    </div>
                    <div className="mt-1 text-xs text-gray-500">
                      greatbeans.com
                    </div>
                  </div>
                </div>
              </div>
            </div>
          )}

          {/* Content Preview */}
          <div className="flex justify-center p-4">
            <div
              className="overflow-hidden rounded-lg border shadow-lg transition-all duration-300"
              style={{
                width: deviceConfig.width,
                height:
                  selectedDevice === 'desktop' ? 'auto' : deviceConfig.height,
                maxWidth: '100%',
              }}
            >
              {/* Mock Browser Header */}
              <div className="flex items-center gap-2 bg-gray-100 px-3 py-2 text-xs">
                <div className="flex gap-1">
                  <div className="h-2 w-2 rounded-full bg-red-400"></div>
                  <div className="h-2 w-2 rounded-full bg-yellow-400"></div>
                  <div className="h-2 w-2 rounded-full bg-green-400"></div>
                </div>
                <div className="flex-1 rounded bg-white px-2 py-1 text-gray-600">
                  greatbeans.com{previewUrl}
                </div>
              </div>

              {/* Content */}
              <div
                className="overflow-auto bg-white p-6"
                style={{
                  height:
                    selectedDevice === 'desktop' ? 'auto' : 'calc(100% - 32px)',
                }}
              >
                {/* Article Header */}
                <div className="mb-6">
                  {metadata.coverImage && (
                    <div className="mb-4 aspect-video w-full overflow-hidden rounded-lg bg-gray-200">
                      <img
                        src={metadata.coverImage}
                        alt={metadata.title}
                        className="h-full w-full object-cover"
                        onError={e => {
                          e.currentTarget.style.display = 'none';
                          (e.currentTarget
                            .nextElementSibling as HTMLElement)!.style.display =
                            'flex';
                        }}
                      />
                      <div className="hidden h-full w-full items-center justify-center text-gray-500">
                        Cover Image
                      </div>
                    </div>
                  )}

                  <div className="mb-2 flex flex-wrap items-center gap-2 text-sm text-gray-600">
                    <Badge variant="outline" className="capitalize">
                      {contentType.replace('-', ' ')}
