                          '<h3 class="text-lg font-medium mb-2">$1</h3>'
                        )
                        .replace(/\*\*(.*?)\*\*/g, '<strong>$1</strong>')
                        .replace(/\*(.*?)\*/g, '<em>$1</em>')
