// Helper function to get Tailwind classes for colors
const getColorClasses = (
  colorKey: string
): {
  primary: string;
  secondary: string;
  accent: string;
  border: string;
  bg: string;
  text: string;
  bgSecondary: string;
  bgAccent: string;
  textAccent: string;
} => {
  const colorMap: Record<
    string,
    {
      primary: string;
      secondary: string;
      accent: string;
      border: string;
      bg: string;
      text: string;
      bgSecondary: string;
      bgAccent: string;
      textAccent: string;
    }
  > = {
    'gold-500': {
      primary: 'gold-500',
      secondary: 'gold-100',
      accent: 'gold-600',
      border: 'border-gold-500',
      bg: 'bg-gold-500',
      text: 'text-gold-500',
      bgSecondary: 'bg-gold-100',
      bgAccent: 'bg-gold-600',
      textAccent: 'text-gold-600',
    },
    'emerald-600': {
      primary: 'emerald-600',
      secondary: 'emerald-100',
      accent: 'emerald-800',
      border: 'border-emerald-600',
      bg: 'bg-emerald-600',
      text: 'text-emerald-600',
      bgSecondary: 'bg-emerald-100',
      bgAccent: 'bg-emerald-800',
      textAccent: 'text-emerald-800',
    },
    'blue-600': {
      primary: 'blue-600',
      secondary: 'blue-100',
      accent: 'blue-800',
      border: 'border-blue-600',
      bg: 'bg-blue-600',
      text: 'text-blue-600',
      bgSecondary: 'bg-blue-100',
      bgAccent: 'bg-blue-800',
      textAccent: 'text-blue-800',
    },
    'purple-600': {
      primary: 'purple-600',
      secondary: 'purple-100',
      accent: 'purple-800',
      border: 'border-purple-600',
      bg: 'bg-purple-600',
      text: 'text-purple-600',
      bgSecondary: 'bg-purple-100',
      bgAccent: 'bg-purple-800',
      textAccent: 'text-purple-800',
    },
  };

  return colorMap[colorKey] ?? colorMap['gold-500']!;
};

