// Batch download component for multiple PDFs
interface BatchPDFDownloadButtonProps {
  items: Array<{
    type: PDFType;
    entityId: string;
    entityData?: CoffeeProduct | RFQ | Record<string, unknown>;
    filename?: string;
  }>;
  locale?: string;
  options?: PDFDownloadButtonProps['options'];
  variant?: PDFDownloadButtonProps['variant'];
  size?: PDFDownloadButtonProps['size'];
  className?: string;
  children?: React.ReactNode;
  onSuccess?: (filenames: string[]) => void;
  onError?: (_error: Error) => void;
}

export const BatchPDFDownloadButton: React.FC<BatchPDFDownloadButtonProps> = ({
  items,
  locale,
  options = {},
  variant = 'default',
  size = 'default',
  className,
  children,
  onSuccess,
  onError,
}) => {
  const t = useTranslations('pdf.buttons');
  const tBatch = useTranslations('pdf.batch');
  const [isGenerating, setIsGenerating] = React.useState(false);
  const [progress, setProgress] = React.useState(0);

  const handleBatchDownload = async () => {
    if (items.length === 0) return;

    setIsGenerating(true);
    setProgress(0);

    try {
      const filenames: string[] = [];

      for (let i = 0; i < items.length; i++) {
        const item = items[i];
        if (!item) continue;

        // Generate PDF based on type
        const response = await fetch(`/api/pdf/${item.type}`, {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
          },
          body: JSON.stringify({
            [`${item.type === 'productSpec' ? 'productId' : 'rfqId'}`]:
              item.entityId,
            locale,
            options,
          }),
        });

        if (!response.ok) {
          throw new Error(`Failed to generate PDF for ${item.entityId}`);
        }

        const blob = await response.blob();
        const filename =
          item.filename || `${item.type}-${item.entityId}-${Date.now()}.pdf`;

        // Download the file
        downloadPDF(blob, filename);

        filenames.push(filename);
        setProgress(((i + 1) / items.length) * 100);
      }

      onSuccess?.(filenames);
    } catch (err) {
      const _error =
        err instanceof Error ? err : new Error('Batch download failed');
      onError?.(_error);
    } finally {
      setIsGenerating(false);
      setProgress(0);
    }
  };

  return (
    <Button
      variant={variant}
      size={size}
      className={cn(
        'relative',
        isGenerating && 'cursor-not-allowed',
        className
      )}
      disabled={isGenerating || items.length === 0}
      onClick={handleBatchDownload}
    >
      {isGenerating ? (
        <>
          <Loader2 className="mr-2 h-4 w-4 animate-spin" />
          {tBatch('generating.description', { count: items.length })}
          {progress > 0 && (
            <span className="ml-2 text-xs">({Math.round(progress)}%)</span>
          )}
        </>
      ) : (
        <>
          <FileText className="mr-2 h-4 w-4" />
          {children || `${t('generatePdf')} (${items.length})`}
        </>
      )}
    </Button>
  );
};

export default PDFDownloadButton;

'use client';

import Script from 'next/script';

import {
  AdvancedSEOMetadata,
  advancedSEOManager,
  type SchemaOrgData,
} from '@/shared/utils/advanced-seo-manager';
import {
  schemaGenerators,
  type CoffeeProductData,
  type B2BServiceData,
  type ArticleData,
  type MarketReportData,
  type OriginStoryData,
} from '@/shared/utils/schema-generators';

/**
 * Enhanced SEO Head Component for The Great Beans
 * Provides comprehensive Technical SEO including:
 * - Advanced meta tags and Open Graph optimization
 * - Schema.org structured data for all content types
 * - International SEO with hreflang
 * - Core Web Vitals optimization
 * - AI and voice search optimization
 */

export interface EnhancedSEOProps {
  // Basic SEO metadata
  metadata: AdvancedSEOMetadata;

  // Content-specific data for Schema.org generation
  productData?: CoffeeProductData;
  serviceData?: B2BServiceData;
  articleData?: ArticleData;
  reportData?: MarketReportData;
  originStoryData?: OriginStoryData;

  // Collection page data
  collectionData?: {
    items: Array<{ name: string; url: string; description?: string }>;
    collectionType: 'products' | 'articles' | 'services' | 'reports';
  };

  // Breadcrumb navigation
  breadcrumbs?: Array<{ name: string; url: string }>;

  // FAQ data for AI optimization
  faqs?: Array<{ question: string; answer: string }>;

  // Custom structured data schemas
  customSchemas?: SchemaOrgData[];

  // Performance optimization
  preloadResources?: Array<{
    href: string;
    as: 'image' | 'font' | 'script' | 'style';
    type?: string;
    crossOrigin?: 'anonymous' | 'use-credentials';
  }>;

  // Analytics and tracking
  enableAnalytics?: boolean;
  enableCoreWebVitalsTracking?: boolean;
}

export function EnhancedSEOHead({
  metadata,
  productData,
  serviceData,
  articleData,
  reportData,
  originStoryData,
  collectionData,
  breadcrumbs,
  faqs,
  customSchemas = [],
  preloadResources = [],
  enableAnalytics = true,
  enableCoreWebVitalsTracking = true,
}: EnhancedSEOProps) {
  // Generate all structured data schemas
  const schemas: SchemaOrgData[] = [];

  // Always include organization and website schemas
  schemas.push(advancedSEOManager.generateOrganizationSchema());
  schemas.push(advancedSEOManager.generateWebsiteSchema(metadata.locale));

  // Add breadcrumb schema if provided
  if (breadcrumbs && breadcrumbs.length > 0) {
    schemas.push(advancedSEOManager.generateBreadcrumbSchema(breadcrumbs));
  }

  // Add FAQ schema if provided
  if (faqs && faqs.length > 0) {
    schemas.push(advancedSEOManager.generateFAQSchema(faqs));
  }

  // Add content-specific schemas
  if (productData) {
    schemas.push(
      schemaGenerators.generateCoffeeProductSchema(
        productData,
        metadata.locale
      )
    );
  }

  if (serviceData) {
    schemas.push(
      schemaGenerators.generateB2BServiceSchema(serviceData, metadata.locale)
    );
  }

  if (articleData) {
    schemas.push(
      schemaGenerators.generateArticleSchema(articleData, metadata.locale)
    );
  }

  if (reportData) {
    schemas.push(
      schemaGenerators.generateMarketReportSchema(reportData, metadata.locale)
    );
  }

  if (originStoryData) {
    schemas.push(
      schemaGenerators.generateOriginStorySchema(
        originStoryData,
        metadata.locale
      )
    );
  }

  if (collectionData) {
    schemas.push(
      schemaGenerators.generateCollectionPageSchema(
        metadata.title,
        metadata.description,
        collectionData.items,
        metadata.locale,
        collectionData.collectionType
      )
    );
  }

  // Add custom schemas
  schemas.push(...customSchemas);

  // Validate all schemas
  const validSchemas = schemas.filter(schema =>
    advancedSEOManager.validateStructuredData(schema)
  );

  // Generate Next.js metadata
  const nextMetadata = advancedSEOManager.generateMetadata(metadata);

  return (
    <>
      {/* Preload critical resources */}
      {preloadResources.map((resource, index) => (
        <link
          // eslint-disable-next-line react/no-array-index-key
          key={`preload-${resource.href}-${index}`}
          rel="preload"
          href={resource.href}
          as={resource.as}
          type={resource.type}
          crossOrigin={resource.crossOrigin}
        />
      ))}

      {/* DNS prefetch for external resources */}
      <link rel="dns-prefetch" href="//fonts.googleapis.com" />
      <link rel="dns-prefetch" href="//www.google-analytics.com" />
      <link rel="dns-prefetch" href="//www.googletagmanager.com" />
      <link rel="dns-prefetch" href="//res.cloudinary.com" />

      {/* Preconnect to critical third-party origins */}
      <link rel="preconnect" href="https://fonts.googleapis.com" />
      <link
        rel="preconnect"
        href="https://fonts.gstatic.com"
        crossOrigin="anonymous"
      />
      <link rel="preconnect" href="https://res.cloudinary.com" />

      {/* Structured Data - JSON-LD */}
      {validSchemas.map((schema, index) => (
        <Script
          // eslint-disable-next-line react/no-array-index-key
          key={`schema-${index}`}
          id={`structured-data-${index}`}
          type="application/ld+json"
          strategy="afterInteractive"
          dangerouslySetInnerHTML={{
            __html: JSON.stringify(schema, null, 0),
          }}
        />
      ))}

      {/* Enhanced meta tags for AI and voice search */}
      <meta
        name="robots"
        content={
          typeof nextMetadata.robots === 'string'
            ? nextMetadata.robots
            : 'index, follow'
        }
      />
      <meta
        name="googlebot"
        content="index, follow, max-snippet:-1, max-image-preview:large, max-video-preview:-1"
      />
      <meta
        name="bingbot"
        content="index, follow, max-snippet:-1, max-image-preview:large, max-video-preview:-1"
      />

      {/* Content classification for AI */}
      <meta name="content-type" content={metadata.contentType} />
      <meta name="content-language" content={metadata.locale} />
      <meta
        name="audience"
        content="business professionals, coffee industry, B2B buyers"
      />
      <meta
        name="subject"
        content="coffee export, Vietnamese coffee, B2B coffee solutions"
      />
      <meta
        name="classification"
        content="business, agriculture, food industry, international trade"
      />

      {/* Enhanced Open Graph for better social sharing */}
      <meta property="og:site_name" content="The Great Beans" />
      <meta property="og:locale" content={metadata.locale} />
      {metadata.alternateLocales?.map(locale => (
        <meta key={locale} property="og:locale:alternate" content={locale} />
      ))}

      {/* Twitter Card enhancements */}
      <meta name="twitter:site" content="@thegreatbeans" />
      <meta name="twitter:creator" content="@thegreatbeans" />
      <meta name="twitter:domain" content="thegreatbeans.com" />

      {/* Enhanced mobile optimization */}
      <meta
        name="viewport"
        content="width=device-width, initial-scale=1, shrink-to-fit=no, viewport-fit=cover"
      />
      <meta name="mobile-web-app-capable" content="yes" />
      <meta name="apple-mobile-web-app-capable" content="yes" />
      <meta name="apple-mobile-web-app-status-bar-style" content="default" />
      <meta name="apple-mobile-web-app-title" content="The Great Beans" />
      <meta name="application-name" content="The Great Beans" />

      {/* Security headers */}
      <meta httpEquiv="X-Content-Type-Options" content="nosniff" />
      <meta httpEquiv="X-Frame-Options" content="DENY" />
      <meta httpEquiv="X-XSS-Protection" content="1; mode=block" />
      <meta name="referrer" content="strict-origin-when-cross-origin" />

      {/* Performance hints */}
      <meta httpEquiv="Accept-CH" content="DPR, Viewport-Width, Width" />
      <meta
        name="format-detection"
        content="telephone=no, date=no, email=no, address=no"
      />

      {/* Favicon and app icons */}
      <link rel="icon" type="image/x-icon" href="/favicon.ico" />
      <link
        rel="icon"
        type="image/png"
        sizes="16x16"
        href="/icons/favicon-16x16.png"
      />
      <link
        rel="icon"
        type="image/png"
        sizes="32x32"
        href="/icons/favicon-32x32.png"
      />
      <link
        rel="apple-touch-icon"
        sizes="180x180"
        href="/icons/apple-touch-icon.png"
      />
      <link rel="manifest" href="/manifest.json" />

      {/* Theme colors */}
      <meta name="theme-color" content="#8B4513" />
      <meta name="msapplication-TileColor" content="#8B4513" />
      <meta name="msapplication-config" content="/browserconfig.xml" />

      {/* Analytics and tracking */}
      {enableAnalytics && (
        <>
          {/* Google Analytics 4 */}
          <Script
            src="https://www.googletagmanager.com/gtag/js?id=GA_MEASUREMENT_ID"
            strategy="afterInteractive"
          />
          <Script id="google-analytics" strategy="afterInteractive">
            {`
              window.dataLayer = window.dataLayer || [];
              function gtag(){dataLayer.push(arguments);}
              gtag('js', new Date());
              gtag('config', 'GA_MEASUREMENT_ID', {
                page_title: '${metadata.title}',
                page_location: window.location.href,
                content_group1: '${metadata.contentType}',
                content_group2: '${metadata.locale}',
                custom_map: {
                  'dimension1': 'content_type',
                  'dimension2': 'locale',
                  'dimension3': 'user_type'
                }
              });
            `}
          </Script>

          {/* Enhanced ecommerce tracking for B2B */}
          {(productData || serviceData) && (
            <Script id="enhanced-ecommerce" strategy="afterInteractive">
              {`
                gtag('event', 'view_item', {
                  currency: '${productData?.price?.currency || 'USD'}',
                  value: ${productData?.price?.amount || 0},
                  items: [{
                    item_id: '${productData?.id || serviceData?.id}',
                    item_name: '${productData?.name || serviceData?.name}',
                    item_category: '${productData ? 'Coffee Product' : 'B2B Service'}',
                    item_variant: '${productData?.variety || serviceData?.serviceType}',
                    price: ${productData?.price?.amount || 0},
                    quantity: 1
                  }]
                });
              `}
            </Script>
          )}
        </>
      )}

      {/* Core Web Vitals tracking */}
      {enableCoreWebVitalsTracking && (
        <Script id="core-web-vitals" strategy="afterInteractive">
          {`
            import {getCLS, getFID, getFCP, getLCP, getTTFB} from 'web-vitals';

            function sendToAnalytics(metric) {
              gtag('event', metric.name, {
                event_category: 'Web Vitals',
                event_label: metric.id,
                value: Math.round(metric.name === 'CLS' ? metric.value * 1000 : metric.value),
                non_interaction: true,
                custom_map: {
                  'metric_value': metric.value,
                  'metric_delta': metric.delta,
                  'metric_id': metric.id,
                  'metric_entries': metric.entries.length
                }
              });
            }

            getCLS(sendToAnalytics);
            getFID(sendToAnalytics);
            getFCP(sendToAnalytics);
            getLCP(sendToAnalytics);
            getTTFB(sendToAnalytics);
          `}
        </Script>
      )}

      {/* Schema.org validation script removed for production */}
    </>
  );
}

export default EnhancedSEOHead;

'use client';

import {
  Search,
  TrendingUp,
  AlertTriangle,
  CheckCircle,
  XCircle,
  Info,
  Download,
  RefreshCw,
  Globe,
  Zap,
  Eye,
  Target,
} from 'lucide-react';
import React, { useState } from 'react';

import {
  Alert,
  AlertDescription,
  AlertTitle,
} from '@/presentation/components/ui/alert';
import { Badge } from '@/presentation/components/ui/badge';
import { Button } from '@/presentation/components/ui/button';
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from '@/presentation/components/ui/card';
import { Input } from '@/presentation/components/ui/input';
import { Progress } from '@/presentation/components/ui/progress';
import {
  Tabs,
  TabsContent,
  TabsList,
  TabsTrigger,
} from '@/presentation/components/ui/tabs';
import { createScopedLogger } from '@/shared/utils/logger';
import { type SEOAuditResult } from '@/shared/utils/seo-audit';

const _logger = createScopedLogger('SEODashboard');

interface SEODashboardProps {
  className?: string;
  defaultUrl?: string;
  showBatchAudit?: boolean;
}

interface AuditState {
  loading: boolean;
  result: SEOAuditResult | null;
  error: string | null;
}

interface BatchAuditState {
  loading: boolean;
  results: Array<{ url: string; audit: SEOAuditResult }>;
  summary: {
    totalUrls: number;
    successful: number;
    failed: number;
    averageScore: number;
    totalIssues: number;
  } | null;
  error: string | null;
}

export function SEODashboard({
  className = '',
  defaultUrl = '',
  showBatchAudit = true,
}: SEODashboardProps) {
  const [url, setUrl] = useState(defaultUrl);
  const [batchUrls, setBatchUrls] = useState('');
  const [auditState, setAuditState] = useState<AuditState>({
    loading: false,
    result: null,
    error: null,
  });
  const [batchState, setBatchState] = useState<BatchAuditState>({
    loading: false,
    results: [],
    summary: null,
    error: null,
  });

  // Perform single URL audit
  const performAudit = async () => {
    if (!url.trim()) return;

    setAuditState({ loading: true, result: null, error: null });

    try {
      const response = await fetch('/api/seo/audit', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ url: url.trim() }),
      });

      const data = await response.json();

      if (!response.ok) {
        throw new Error(data.message || 'Audit failed');
      }

      setAuditState({ loading: false, result: data.audit, error: null });
    } catch (_error) {
      setAuditState({
        loading: false,
        result: null,
        error: _error instanceof Error ? _error.message : 'Unknown error',
      });
    }
  };

  // Perform batch audit
  const performBatchAudit = async () => {
    const urls = batchUrls
      .split('\n')
      .map(url => url.trim())
      .filter(url => url.length > 0);

    if (urls.length === 0) return;

    setBatchState({ loading: true, results: [], summary: null, error: null });

    try {
      const response = await fetch('/api/seo/audit/batch', {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ urls }),
      });

      const data = await response.json();

      if (!response.ok) {
        throw new Error(data.message || 'Batch audit failed');
      }

      setBatchState({
        loading: false,
        results: data.results,
        summary: data.summary,
        error: null,
      });
    } catch (_error) {
      setBatchState({
        loading: false,
        results: [],
        summary: null,
        error: _error instanceof Error ? _error.message : 'Unknown error',
      });
    }
  };

  // Download audit report
  const downloadReport = async () => {
    if (!url.trim()) return;

    try {
      const response = await fetch('/api/seo/audit', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ url: url.trim(), format: 'report' }),
      });

      if (!response.ok) {
        throw new Error('Failed to generate report');
      }

      const blob = await response.blob();
      const downloadUrl = window.URL.createObjectURL(blob);
      const link = document.createElement('a');
      link.href = downloadUrl;
      link.download = `seo-audit-${new Date().toISOString().split('T')[0]}.md`;
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
      window.URL.revokeObjectURL(downloadUrl);
    } catch (_error) {
      // Download error logging removed for production
    }
  };

  // Get score color
  const getScoreColor = (score: number) => {
    if (score >= 90) return 'text-green-600';
    if (score >= 70) return 'text-yellow-600';
    return 'text-red-600';
  };

  // Get issue icon
  const getIssueIcon = (type: string) => {
    switch (type) {
      case 'error':
        return <XCircle className="h-4 w-4 text-red-500" />;
      case 'warning':
        return <AlertTriangle className="h-4 w-4 text-yellow-500" />;
      case 'info':
        return <Info className="h-4 w-4 text-blue-500" />;
      default:
        return <Info className="h-4 w-4 text-gray-500" />;
    }
  };

  // Get impact badge variant
  const getImpactVariant = (impact: string) => {
    switch (impact) {
      case 'high':
        return 'destructive';
      case 'medium':
        return 'default';
      case 'low':
        return 'secondary';
      default:
        return 'outline';
    }
  };

  return (
    <div className={`space-y-6 ${className}`}>
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-3xl font-bold tracking-tight">SEO Dashboard</h2>
          <p className="text-muted-foreground">
            Monitor and optimize your website&apos;s SEO performance
          </p>
        </div>
        <div className="flex items-center space-x-2">
          <Button
            variant="outline"
            size="sm"
            onClick={downloadReport}
            disabled={!auditState.result || auditState.loading}
          >
            <Download className="mr-2 h-4 w-4" />
            Download Report
          </Button>
        </div>
      </div>

      <Tabs defaultValue="single" className="space-y-4">
        <TabsList>
          <TabsTrigger value="single">Single URL Audit</TabsTrigger>
          {showBatchAudit && (
            <TabsTrigger value="batch">Batch Audit</TabsTrigger>
          )}
          <TabsTrigger value="overview">Overview</TabsTrigger>
        </TabsList>

        {/* Single URL Audit */}
        <TabsContent value="single" className="space-y-4">
          <Card>
            <CardHeader>
              <CardTitle className="flex items-center">
                <Search className="mr-2 h-5 w-5" />
                SEO Audit
              </CardTitle>
              <CardDescription>
                Analyze a single page for SEO optimization opportunities
              </CardDescription>
            </CardHeader>
            <CardContent className="space-y-4">
              <div className="flex space-x-2">
                <Input
                  placeholder="Enter URL to audit (e.g., https://example.com)"
                  value={url}
                  onChange={e => setUrl(e.target.value)}
                  onKeyPress={e => e.key === 'Enter' && performAudit()}
                />
                <Button
                  onClick={performAudit}
                  disabled={auditState.loading || !url.trim()}
                >
                  {auditState.loading ? (
                    <RefreshCw className="mr-2 h-4 w-4 animate-spin" />
                  ) : (
                    <Search className="mr-2 h-4 w-4" />
                  )}
                  Audit
                </Button>
              </div>

              {auditState.error && (
                <Alert variant="destructive">
                  <AlertTriangle className="h-4 w-4" />
                  <AlertTitle>Error</AlertTitle>
                  <AlertDescription>{auditState.error}</AlertDescription>
                </Alert>
              )}

              {auditState.result && (
                <div className="space-y-6">
                  {/* Score Overview */}
                  <Card>
                    <CardHeader>
                      <CardTitle className="flex items-center justify-between">
                        <span>SEO Score</span>
                        <span
                          className={`text-2xl font-bold ${getScoreColor(auditState.result.score)}`}
                        >
                          {auditState.result.score}/100
                        </span>
                      </CardTitle>
                    </CardHeader>
                    <CardContent>
                      <Progress
                        value={auditState.result.score}
                        className="w-full"
                      />
                    </CardContent>
                  </Card>

                  {/* Issues */}
                  {auditState.result.issues.length > 0 && (
                    <Card>
                      <CardHeader>
                        <CardTitle className="flex items-center">
                          <AlertTriangle className="mr-2 h-5 w-5" />
                          Issues ({auditState.result.issues.length})
                        </CardTitle>
                      </CardHeader>
                      <CardContent>
                        <div className="space-y-3">
                          {auditState.result.issues.map((issue, index) => (
                            <div
                              // eslint-disable-next-line react/no-array-index-key
                              key={`issue-${issue.title}-${index}`}
                              className="flex items-start space-x-3 rounded-lg border p-3"
                            >
                              {getIssueIcon(issue.type)}
                              <div className="flex-1 space-y-1">
                                <div className="flex items-center justify-between">
                                  <h4 className="font-medium">{issue.title}</h4>
                                  <Badge
                                    variant={getImpactVariant(issue.impact)}
                                  >
                                    {issue.impact} impact
                                  </Badge>
                                </div>
                                <p className="text-sm text-muted-foreground">
                                  {issue.description}
                                </p>
                                <p className="text-sm font-medium text-blue-600">
                                  💡 {issue.recommendation}
                                </p>
                              </div>
                            </div>
                          ))}
                        </div>
                      </CardContent>
                    </Card>
                  )}

                  {/* Recommendations */}
                  {auditState.result.recommendations.length > 0 && (
                    <Card>
                      <CardHeader>
                        <CardTitle className="flex items-center">
                          <Target className="mr-2 h-5 w-5" />
                          Recommendations (
                          {auditState.result.recommendations.length})
                        </CardTitle>
                      </CardHeader>
                      <CardContent>
                        <div className="space-y-3">
                          {auditState.result.recommendations.map(
                            (rec, index) => (
                              <div
                                // eslint-disable-next-line react/no-array-index-key
                                key={`recommendation-${rec.title}-${index}`}
                                className="space-y-2 rounded-lg border p-3"
                              >
                                <div className="flex items-center justify-between">
                                  <h4 className="font-medium">{rec.title}</h4>
                                  <div className="flex space-x-2">
                                    <Badge variant="outline">
                                      {rec.priority} priority
                                    </Badge>
                                    <Badge variant="secondary">
                                      {rec.effort} effort
                                    </Badge>
                                  </div>
                                </div>
                                <p className="text-sm text-muted-foreground">
                                  {rec.description}
                                </p>
                                <p className="text-sm font-medium">
                                  🔧 {rec.implementation}
                                </p>
                              </div>
                            )
                          )}
                        </div>
                      </CardContent>
                    </Card>
                  )}

                  {/* Detailed Metrics */}
                  <div className="grid grid-cols-1 gap-4 md:grid-cols-2 lg:grid-cols-3">
                    {/* Metadata */}
                    <Card>
                      <CardHeader>
                        <CardTitle className="flex items-center text-sm">
                          <Eye className="mr-2 h-4 w-4" />
                          Metadata
                        </CardTitle>
                      </CardHeader>
                      <CardContent className="space-y-2">
                        <div className="flex justify-between text-sm">
                          <span>Title</span>
                          <span
                            className={
                              auditState.result.metadata.title.optimal
                                ? 'text-green-600'
                                : 'text-red-600'
                            }
                          >
                            {auditState.result.metadata.title.present
                              ? '✓'
                              : '✗'}
                          </span>
                        </div>
                        <div className="flex justify-between text-sm">
                          <span>Description</span>
                          <span
                            className={
                              auditState.result.metadata.description.optimal
                                ? 'text-green-600'
                                : 'text-red-600'
                            }
                          >
                            {auditState.result.metadata.description.present
                              ? '✓'
                              : '✗'}
                          </span>
                        </div>
                        <div className="flex justify-between text-sm">
                          <span>Open Graph</span>
                          <span
                            className={
                              auditState.result.metadata.openGraph.complete
                                ? 'text-green-600'
                                : 'text-red-600'
                            }
                          >
                            {auditState.result.metadata.openGraph.present
                              ? '✓'
                              : '✗'}
                          </span>
                        </div>
                      </CardContent>
                    </Card>

                    {/* Structured Data */}
                    <Card>
                      <CardHeader>
                        <CardTitle className="flex items-center text-sm">
                          <Globe className="mr-2 h-4 w-4" />
                          Structured Data
                        </CardTitle>
                      </CardHeader>
                      <CardContent className="space-y-2">
                        <div className="flex justify-between text-sm">
                          <span>Present</span>
                          <span
                            className={
                              auditState.result.structuredData.present
                                ? 'text-green-600'
                                : 'text-red-600'
                            }
                          >
                            {auditState.result.structuredData.present
                              ? '✓'
                              : '✗'}
                          </span>
                        </div>
                        <div className="flex justify-between text-sm">
                          <span>Valid</span>
                          <span
                            className={
                              auditState.result.structuredData.valid
                                ? 'text-green-600'
                                : 'text-red-600'
                            }
                          >
                            {auditState.result.structuredData.valid ? '✓' : '✗'}
                          </span>
                        </div>
                        <div className="flex justify-between text-sm">
                          <span>Coverage</span>
                          <span>
                            {auditState.result.structuredData.coverage}%
                          </span>
                        </div>
                      </CardContent>
                    </Card>

                    {/* Performance */}
                    <Card>
                      <CardHeader>
                        <CardTitle className="flex items-center text-sm">
                          <Zap className="mr-2 h-4 w-4" />
                          Performance
                        </CardTitle>
                      </CardHeader>
                      <CardContent className="space-y-2">
                        <div className="flex justify-between text-sm">
                          <span>LCP</span>
                          <span>
                            {
                              auditState.result.performance.coreWebVitals.lcp
                                .rating
                            }
                          </span>
                        </div>
                        <div className="flex justify-between text-sm">
                          <span>FID</span>
                          <span>
                            {
                              auditState.result.performance.coreWebVitals.fid
                                .rating
                            }
                          </span>
                        </div>
                        <div className="flex justify-between text-sm">
                          <span>CLS</span>
                          <span>
                            {
                              auditState.result.performance.coreWebVitals.cls
                                .rating
                            }
                          </span>
                        </div>
                      </CardContent>
                    </Card>
                  </div>
                </div>
              )}
            </CardContent>
          </Card>
        </TabsContent>

        {/* Batch Audit */}
        {showBatchAudit && (
          <TabsContent value="batch" className="space-y-4">
            <Card>
              <CardHeader>
                <CardTitle className="flex items-center">
                  <TrendingUp className="mr-2 h-5 w-5" />
                  Batch SEO Audit
                </CardTitle>
                <CardDescription>
                  Audit multiple URLs at once (max 10 URLs)
                </CardDescription>
              </CardHeader>
              <CardContent className="space-y-4">
                <div className="space-y-2">
                  <label className="text-sm font-medium">
                    URLs (one per line)
                  </label>
                  <textarea
                    className="h-32 w-full resize-none rounded-md border p-3"
                    placeholder="https://example.com/page1&#10;https://example.com/page2&#10;https://example.com/page3"
                    value={batchUrls}
                    onChange={e => setBatchUrls(e.target.value)}
                  />
                </div>

                <Button
                  onClick={performBatchAudit}
                  disabled={batchState.loading || !batchUrls.trim()}
                  className="w-full"
                >
                  {batchState.loading ? (
                    <RefreshCw className="mr-2 h-4 w-4 animate-spin" />
                  ) : (
                    <Search className="mr-2 h-4 w-4" />
                  )}
                  Run Batch Audit
                </Button>

                {batchState.error && (
                  <Alert variant="destructive">
                    <AlertTriangle className="h-4 w-4" />
                    <AlertTitle>Error</AlertTitle>
                    <AlertDescription>{batchState.error}</AlertDescription>
                  </Alert>
                )}

                {batchState.summary && (
                  <div className="space-y-4">
                    {/* Summary */}
                    <Card>
                      <CardHeader>
                        <CardTitle>Batch Summary</CardTitle>
                      </CardHeader>
                      <CardContent>
                        <div className="grid grid-cols-2 gap-4 md:grid-cols-5">
                          <div className="text-center">
                            <div className="text-2xl font-bold">
                              {batchState.summary.totalUrls}
                            </div>
                            <div className="text-sm text-muted-foreground">
                              Total URLs
                            </div>
                          </div>
                          <div className="text-center">
                            <div className="text-2xl font-bold text-green-600">
                              {batchState.summary.successful}
                            </div>
                            <div className="text-sm text-muted-foreground">
                              Successful
                            </div>
                          </div>
                          <div className="text-center">
                            <div className="text-2xl font-bold text-red-600">
                              {batchState.summary.failed}
                            </div>
                            <div className="text-sm text-muted-foreground">
                              Failed
                            </div>
                          </div>
                          <div className="text-center">
                            <div
                              className={`text-2xl font-bold ${getScoreColor(batchState.summary.averageScore)}`}
                            >
                              {batchState.summary.averageScore}
                            </div>
                            <div className="text-sm text-muted-foreground">
                              Avg Score
                            </div>
                          </div>
                          <div className="text-center">
                            <div className="text-2xl font-bold text-yellow-600">
                              {batchState.summary.totalIssues}
                            </div>
                            <div className="text-sm text-muted-foreground">
                              Total Issues
                            </div>
                          </div>
                        </div>
                      </CardContent>
                    </Card>

                    {/* Results */}
                    <Card>
                      <CardHeader>
                        <CardTitle>Results</CardTitle>
                      </CardHeader>
                      <CardContent>
                        <div className="space-y-3">
                          {batchState.results.map((result, index) => (
                            <div
                              // eslint-disable-next-line react/no-array-index-key
                              key={`batch-result-${result.url}-${index}`}
                              className="flex items-center justify-between rounded-lg border p-3"
                            >
                              <div className="flex-1">
                                <div className="truncate font-medium">
                                  {result.url}
                                </div>
                                <div className="text-sm text-muted-foreground">
                                  {result.audit.issues.length} issues found
                                </div>
                              </div>
                              <div className="flex items-center space-x-3">
                                <div
                                  className={`text-lg font-bold ${getScoreColor(result.audit.score)}`}
                                >
                                  {result.audit.score}
                                </div>
                                <Progress
                                  value={result.audit.score}
                                  className="w-20"
                                />
                              </div>
                            </div>
                          ))}
                        </div>
                      </CardContent>
                    </Card>
                  </div>
                )}
              </CardContent>
            </Card>
          </TabsContent>
        )}

        {/* Overview */}
        <TabsContent value="overview" className="space-y-4">
          <div className="grid grid-cols-1 gap-4 md:grid-cols-2 lg:grid-cols-4">
            <Card>
              <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
                <CardTitle className="text-sm font-medium">SEO Score</CardTitle>
                <TrendingUp className="h-4 w-4 text-muted-foreground" />
              </CardHeader>
              <CardContent>
                <div className="text-2xl font-bold">
                  {auditState.result?.score || '--'}/100
                </div>
                <p className="text-xs text-muted-foreground">
                  Overall SEO performance
                </p>
              </CardContent>
            </Card>

            <Card>
              <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
                <CardTitle className="text-sm font-medium">Issues</CardTitle>
                <AlertTriangle className="h-4 w-4 text-muted-foreground" />
              </CardHeader>
              <CardContent>
                <div className="text-2xl font-bold">
                  {auditState.result?.issues.length || 0}
                </div>
                <p className="text-xs text-muted-foreground">
                  Items need attention
                </p>
              </CardContent>
            </Card>

            <Card>
              <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
                <CardTitle className="text-sm font-medium">
                  Structured Data
