        responses.push({
          url: response.url(),
          headers: response.headers(),
          status: response.status(),
        });
      });

      await page.reload();

      // Check that static assets have cache headers
      const staticAssets = responses.filter(
        r =>
          r.url.includes('.js') ||
          r.url.includes('.css') ||
          r.url.includes('.png') ||
          r.url.includes('.jpg')
      );

